INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-001', 'HDSAT-RW-M13-INFO-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A small museum''s visitor-services team is preparing a note for its annual report describing how attendance changed across the year.', 'Which choice most effectively uses data from the table to describe the pattern in attendance?', '[{"id": "A", "text": "Winter drew more visitors than spring."}, {"id": "B", "text": "Summer and fall together drew fewer than 3,000 visitors."}, {"id": "C", "text": "Summer drew 2,180 visitors, more than twice the 980 who visited in winter."}, {"id": "D", "text": "Fall drew nearly twice as many visitors as summer."}]'::jsonb, '{"type": "table", "caption": "Seasonal attendance at a small museum", "headers": ["Season", "Visitors"], "rows": [["Spring", "1,240"], ["Summer", "2,180"], ["Fall", "1,560"], ["Winter", "980"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-001', 'C', ARRAY['C']::TEXT[], 'Summer attendance reached 2,180 while winter attendance was 980, and 2,180 is indeed more than twice 980. The other choices contradict the table.', '{"D": "Fall recorded 1,560 visitors, fewer than summer''s 2,180, so it was not nearly twice as many.", "A": "Winter recorded 980 visitors, fewer than spring''s 1,240.", "B": "Summer and fall together recorded 3,740 visitors, well above 3,000."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-002', 'HDSAT-RW-M13-INFO-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A city transportation office is summarizing a week of bike-share activity at one busy docking station.', 'Which choice most effectively uses data from the chart to describe the week?', '[{"id": "A", "text": "Use peaked on Friday at 510 trips, 190 more than on Monday."}, {"id": "B", "text": "Wednesday recorded more trips than Thursday."}, {"id": "C", "text": "Tuesday recorded more trips than any other day."}, {"id": "D", "text": "Thursday recorded fewer trips than Wednesday."}]'::jsonb, '{"type": "bar_chart", "caption": "Bike-share trips from one docking station, by weekday", "x_label": "Day", "y_label": "Trips", "series": [{"label": "Mon", "value": 320}, {"label": "Tue", "value": 410}, {"label": "Wed", "value": 380}, {"label": "Thu", "value": 450}, {"label": "Fri", "value": 510}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-002', 'A', ARRAY['A']::TEXT[], 'Friday''s bar is the tallest at 510, and 510 minus 320 is 190 more than Monday. No other statement matches the five bars.', '{"C": "Tuesday recorded 410 trips, fewer than Friday''s 510.", "B": "Wednesday recorded 380 trips, fewer than Thursday''s 450.", "D": "Thursday recorded 450 trips, more than Wednesday''s 380."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-003', 'HDSAT-RW-M13-INFO-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A botany class tracked the height of a single sunflower seedling once a week for five weeks.', 'Which choice most effectively uses data from the graph to describe the seedling''s growth?', '[{"id": "A", "text": "The seedling grew 18 cm over the four weeks from week 1 to week 5."}, {"id": "B", "text": "The seedling was 11 cm tall in week 4."}, {"id": "C", "text": "The seedling''s height doubled between week 2 and week 4."}, {"id": "D", "text": "The seedling reached a final height of 18 cm."}]'::jsonb, '{"type": "line_chart", "caption": "Sunflower seedling height by week", "x_label": "Week", "y_label": "Height (cm)", "series": [{"label": "1", "value": 4}, {"label": "2", "value": 7}, {"label": "3", "value": 11}, {"label": "4", "value": 16}, {"label": "5", "value": 22}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-003', 'A', ARRAY['A']::TEXT[], 'Height rose from 4 cm in week 1 to 22 cm in week 5, a gain of 18 cm. The remaining choices misread the points or the axis.', '{"B": "Week 4 shows 16 cm; 11 cm is the week 3 height.", "C": "The height went from 7 cm to 16 cm, which is more than double but not exactly double.", "D": "The final height was 22 cm; 18 cm is the amount of growth."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-004', 'HDSAT-RW-M13-INFO-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A garden cooperative recorded monthly rainfall at its demonstration plot and wants to note which month was driest.', 'Which choice most effectively uses data from the table to describe the rainfall?', '[{"id": "A", "text": "May recorded less than 4 cm of rain."}, {"id": "B", "text": "April was the driest month of the four."}, {"id": "C", "text": "July was the driest month at 1.4 cm, less than half of May''s 4.8 cm."}, {"id": "D", "text": "June was wetter than April."}]'::jsonb, '{"type": "table", "caption": "Monthly rainfall at a demonstration garden", "headers": ["Month", "Rainfall (cm)"], "rows": [["April", "3.2"], ["May", "4.8"], ["June", "2.1"], ["July", "1.4"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-004', 'C', ARRAY['C']::TEXT[], 'July''s 1.4 cm is the smallest figure in the table and is less than half of May''s 4.8 cm. The other choices reverse or misstate the values.', '{"D": "June recorded 2.1 cm, less than April''s 3.2 cm.", "B": "April recorded 3.2 cm, well above July''s 1.4 cm.", "A": "May recorded 4.8 cm, which is more than 4 cm."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-005', 'HDSAT-RW-M13-INFO-005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A branch library is comparing how often items in four collections were borrowed during a single month.', 'Which choice most effectively uses data from the table to describe borrowing?', '[{"id": "A", "text": "Science borrowing was higher than history borrowing."}, {"id": "B", "text": "History and science together accounted for more than 500 items."}, {"id": "C", "text": "Fiction borrowing, at 640 items, exceeded the other three collections combined."}, {"id": "D", "text": "Poetry was the most borrowed collection."}]'::jsonb, '{"type": "table", "caption": "Items borrowed by collection in one month", "headers": ["Collection", "Items borrowed"], "rows": [["Fiction", "640"], ["History", "210"], ["Science", "180"], ["Poetry", "95"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-005', 'C', ARRAY['C']::TEXT[], 'The other three collections total 210 + 180 + 95 = 485 items, which is less than fiction''s 640. The remaining choices misstate the ranking or the total.', '{"D": "Poetry had the fewest items borrowed, 95.", "A": "Science had 180, fewer than history''s 210.", "B": "History and science together total 390, not more than 500."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-006', 'HDSAT-RW-M13-INFO-006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A transit authority is reviewing average daily boardings on four bus routes to decide where to add service.', 'Which choice most effectively uses data from the table to identify the route carrying the most riders?', '[{"id": "A", "text": "Route C carried fewer riders than routes A and B combined."}, {"id": "B", "text": "Route A carried the most riders, at 1,150."}, {"id": "C", "text": "Route D carried more riders than route B."}, {"id": "D", "text": "Route C carried 1,420 riders, 550 more than route D."}]'::jsonb, '{"type": "table", "caption": "Average daily boardings by route", "headers": ["Route", "Daily boardings"], "rows": [["A", "1,150"], ["B", "980"], ["C", "1,420"], ["D", "870"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-006', 'D', ARRAY['D']::TEXT[], 'Route C''s 1,420 boardings is the largest figure, and 1,420 minus 870 equals 550. The other statements contradict the table.', '{"B": "Route A''s 1,150 boardings are fewer than route C''s 1,420.", "C": "Route D''s 870 boardings are fewer than route B''s 980.", "A": "Routes A and B together carry 2,130, far more than route C alone."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-007', 'HDSAT-RW-M13-INFO-007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A neighborhood recycling program tallied the material it collected by weight in a single week.', 'Which choice most effectively uses data from the table to describe the week''s collection?', '[{"id": "A", "text": "Metal outweighed glass."}, {"id": "B", "text": "Plastic was the most collected material."}, {"id": "C", "text": "Paper made up 420 kg, more than glass and metal combined."}, {"id": "D", "text": "Paper weighed less than plastic and metal combined."}]'::jsonb, '{"type": "table", "caption": "Recycled material collected in one week (kg)", "headers": ["Material", "Weight (kg)"], "rows": [["Paper", "420"], ["Glass", "180"], ["Metal", "95"], ["Plastic", "260"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-007', 'C', ARRAY['C']::TEXT[], 'Glass and metal together total 275 kg, and paper alone was 420 kg. The other choices reverse the ranking or the comparison.', '{"B": "Plastic was 260 kg, less than paper''s 420 kg.", "A": "Metal was 95 kg, less than glass''s 180 kg.", "D": "Plastic and metal together total 355 kg, less than paper''s 420 kg."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-008', 'HDSAT-RW-M13-INFO-008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A farmers market coordinator is describing how the number of vendors changed over four years.', 'Which choice most effectively uses data from the chart to describe the change?', '[{"id": "A", "text": "The market had 38 vendors in 2021, 7 more than in 2019."}, {"id": "B", "text": "The number of vendors declined every year."}, {"id": "C", "text": "The market had the most vendors in 2020."}, {"id": "D", "text": "The market had 31 vendors in 2021."}]'::jsonb, '{"type": "bar_chart", "caption": "Number of vendors at a weekly farmers market", "x_label": "Year", "y_label": "Vendors", "series": [{"label": "2018", "value": 24}, {"label": "2019", "value": 31}, {"label": "2020", "value": 27}, {"label": "2021", "value": 38}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-008', 'A', ARRAY['A']::TEXT[], 'The 2021 bar is the tallest at 38, and 38 minus 31 equals 7. The remaining choices misread the bars.', '{"C": "2020 shows 27 vendors, fewer than both 2019 and 2021.", "B": "Vendor counts rose in 2019 and again in 2021, so they did not decline every year.", "D": "The 2021 figure is 38; 31 is the 2019 figure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-009', 'HDSAT-RW-M13-INFO-009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A volunteer bird survey counted individuals of a single species at a wetland each spring for five years.', 'Which choice most effectively uses data from the graph to summarize the survey?', '[{"id": "A", "text": "The highest count came in 2018."}, {"id": "B", "text": "The count fell every year after 2016."}, {"id": "C", "text": "The count rose from 120 birds in 2016 to 210 in 2020, an increase of 90."}, {"id": "D", "text": "The count doubled between 2016 and 2019."}]'::jsonb, '{"type": "line_chart", "caption": "Birds counted at a wetland, 2016-2020", "x_label": "Year", "y_label": "Birds counted", "series": [{"label": "2016", "value": 120}, {"label": "2017", "value": 150}, {"label": "2018", "value": 135}, {"label": "2019", "value": 180}, {"label": "2020", "value": 210}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-009', 'C', ARRAY['C']::TEXT[], 'The series starts at 120 and ends at 210, a difference of 90. The other choices contradict the plotted points.', '{"B": "The count rose in three of the four later years, including a rise from 2018 to 2019.", "A": "The 2018 count of 135 is below the counts for 2017, 2019 and 2020.", "D": "Doubling 120 would give 240, well above the 180 recorded in 2019."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-010', 'HDSAT-RW-M13-INFO-010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'The owner of a small coffee stand is comparing daily sales across one workweek.', 'Which choice most effectively uses data from the table to describe the week?', '[{"id": "A", "text": "Thursday''s sales were higher than Friday''s."}, {"id": "B", "text": "Wednesday was the busiest day of the week."}, {"id": "C", "text": "Tuesday''s sales were below 80 cups."}, {"id": "D", "text": "Friday''s 118 cups were the week''s highest, 40 more than Wednesday''s 78."}]'::jsonb, '{"type": "table", "caption": "Cups sold per day at a coffee stand", "headers": ["Day", "Cups sold"], "rows": [["Monday", "84"], ["Tuesday", "92"], ["Wednesday", "78"], ["Thursday", "105"], ["Friday", "118"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-010', 'D', ARRAY['D']::TEXT[], 'Friday has the largest figure in the table, and 118 minus 78 is 40. The other choices contradict the numbers.', '{"B": "Wednesday''s 78 cups are the fewest of the week.", "A": "Thursday sold 105 cups, fewer than Friday''s 118.", "C": "Tuesday sold 92 cups, above 80."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-011', 'HDSAT-RW-M13-INFO-011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A parks department counted visitors at a trailhead over four months to plan maintenance.', 'Which choice most effectively uses data from the table to describe the season''s use?', '[{"id": "A", "text": "March drew more visitors than April."}, {"id": "B", "text": "February''s visitor count fell below January''s."}, {"id": "C", "text": "April''s visitors exceeded March and February combined."}, {"id": "D", "text": "April''s 980 visitors were nearly three times January''s 340."}]'::jsonb, '{"type": "table", "caption": "Trailhead visitors by month", "headers": ["Month", "Visitors"], "rows": [["January", "340"], ["February", "410"], ["March", "620"], ["April", "980"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-011', 'D', ARRAY['D']::TEXT[], 'Three times January''s 340 is 1,020, so April''s 980 is nearly, though not quite, triple. The other choices contradict the table.', '{"A": "March drew 620, fewer than April''s 980.", "B": "February drew 410, more than January''s 340.", "C": "March and February together drew 1,030, more than April''s 980."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-012', 'HDSAT-RW-M13-INFO-012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'Marine researchers surveyed coral cover at one reef site every five years and reported the results as a percentage.', 'Which choice most effectively uses data from the chart to describe the trend?', '[{"id": "A", "text": "Coral cover was lowest in 2020."}, {"id": "B", "text": "Coral cover in 2005 was lower than in 2010."}, {"id": "C", "text": "Coral cover reached its lowest point in 2015, at 18%."}, {"id": "D", "text": "Coral cover rose steadily at every survey."}]'::jsonb, '{"type": "bar_chart", "caption": "Coral cover at a reef site by year", "x_label": "Year", "y_label": "Coral cover (%)", "series": [{"label": "2005", "value": 32}, {"label": "2010", "value": 24}, {"label": "2015", "value": 18}, {"label": "2020", "value": 26}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-012', 'C', ARRAY['C']::TEXT[], 'The 2015 bar is the shortest at 18%, making it the lowest of the four surveys. The other choices reverse the pattern.', '{"D": "Cover fell from 2005 to 2015 before rising in 2020.", "A": "2020 recorded 26%, above the 2015 low.", "B": "2005 recorded 32%, higher than 2010''s 24%."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-013', 'HDSAT-RW-M13-INFO-013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A community energy group recorded the electricity generated by a small turbine over four months.', 'Which choice most effectively uses data from the table to identify the strongest month?', '[{"id": "A", "text": "February''s output exceeded March''s."}, {"id": "B", "text": "April produced the most electricity of the four months."}, {"id": "C", "text": "January produced the least electricity."}, {"id": "D", "text": "March produced 510 MWh, 130 more than February."}]'::jsonb, '{"type": "table", "caption": "Electricity generated by a community turbine (MWh)", "headers": ["Month", "Output (MWh)"], "rows": [["January", "420"], ["February", "380"], ["March", "510"], ["April", "460"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-013', 'D', ARRAY['D']::TEXT[], 'March''s 510 MWh is the largest figure, and 510 minus 380 is 130. The other statements contradict the table.', '{"B": "April produced 460 MWh, less than March''s 510.", "A": "February produced 380 MWh, less than March''s 510.", "C": "January produced 420 MWh, more than February''s 380."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-014', 'HDSAT-RW-M13-INFO-014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A tutoring center tracked the number of students attending its free after-school sessions.', 'Which choice most effectively uses data from the graph to describe attendance?', '[{"id": "A", "text": "Attendance was highest in week 4."}, {"id": "B", "text": "Attendance fell every week after week 2."}, {"id": "C", "text": "Attendance reached 30 students in week 5, 18 more than in week 1."}, {"id": "D", "text": "Attendance doubled between week 3 and week 4."}]'::jsonb, '{"type": "line_chart", "caption": "Students attending after-school tutoring by week", "x_label": "Week", "y_label": "Students", "series": [{"label": "1", "value": 12}, {"label": "2", "value": 18}, {"label": "3", "value": 15}, {"label": "4", "value": 24}, {"label": "5", "value": 30}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-014', 'C', ARRAY['C']::TEXT[], 'The final point is 30 and the first is 12, a difference of 18. The other choices misstate the plotted values.', '{"B": "Attendance rose from 15 in week 3 to 24 in week 4 and 30 in week 5.", "A": "Week 5 is higher, at 30 students.", "D": "Doubling week 3''s 15 would give 30, but week 4 shows 24."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-015', 'HDSAT-RW-M13-INFO-015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A food bank reported the number of donation boxes it received each month during a spring drive.', 'Which choice most effectively uses data from the table to describe the drive?', '[{"id": "A", "text": "April brought fewer boxes than February and March combined."}, {"id": "B", "text": "April brought 360 boxes, 120 more than January."}, {"id": "C", "text": "February brought fewer boxes than January."}, {"id": "D", "text": "March brought the most boxes of any month."}]'::jsonb, '{"type": "table", "caption": "Donation boxes received, January to April", "headers": ["Month", "Boxes"], "rows": [["January", "240"], ["February", "300"], ["March", "280"], ["April", "360"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-015', 'B', ARRAY['B']::TEXT[], 'April''s 360 boxes are the highest count, and 360 minus 240 is 120. The other choices contradict the table.', '{"D": "March brought 280 boxes, fewer than April''s 360.", "C": "February brought 300 boxes, more than January''s 240.", "A": "February and March together brought 580 boxes, more than April''s 360."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-016', 'HDSAT-RW-M13-INFO-016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A hydrologist measured the average flow of a small river each month from May through August.', 'Which choice most effectively uses data from the chart to describe the flow?', '[{"id": "A", "text": "Flow was highest in June at 62, 40 more than in August."}, {"id": "B", "text": "August''s flow was higher than July''s."}, {"id": "C", "text": "Flow was highest in July."}, {"id": "D", "text": "May had the lowest flow of the four months."}]'::jsonb, '{"type": "bar_chart", "caption": "Average river flow by month", "x_label": "Month", "y_label": "Flow (cubic meters per second)", "series": [{"label": "May", "value": 45}, {"label": "June", "value": 62}, {"label": "July", "value": 38}, {"label": "August", "value": 22}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
