INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-017', 'B', ARRAY['B']::TEXT[], 'Saturday''s 340 tickets are the highest count, and 340 minus 210 is 130. The other choices misstate the ranking.', '{"A": "Sunday sold 290 tickets, fewer than Saturday''s 340.", "C": "Friday sold 210 tickets, the fewest of the three.", "D": "Sunday sold 290 tickets, well above 200."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
