INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-019', 'HDSAT-RW-M13-INFO-019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A water district compared average daily household use in four towns.', 'Which choice most effectively uses data from the table to compare the towns?', '[{"id": "A", "text": "Town B had the highest use of the four towns."}, {"id": "B", "text": "Town D used 190 liters per household, 68 more than town C."}, {"id": "C", "text": "Town C used more than town A."}, {"id": "D", "text": "Town A used fewer than 120 liters per household."}]'::jsonb, '{"type": "table", "caption": "Average daily household water use (liters)", "headers": ["Town", "Liters per household"], "rows": [["A", "145"], ["B", "168"], ["C", "122"], ["D", "190"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-019', 'B', ARRAY['B']::TEXT[], 'Town D''s 190 liters is the highest figure, and 190 minus 122 is 68. The other statements contradict the table.', '{"A": "Town B used 168 liters, less than town D''s 190.", "C": "Town C used 122 liters, less than town A''s 145.", "D": "Town A used 145 liters, above 120."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-020', 'HDSAT-RW-M13-INFO-020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A marine survey team counted fish of one species at four reef sites during the same week.', 'Which choice most effectively uses data from the table to compare the sites?', '[{"id": "A", "text": "Reef 2 had the most fish of the four sites."}, {"id": "B", "text": "Reef 1 had more fish than reef 3."}, {"id": "C", "text": "Reef 3 had 102 fish, 38 more than reef 2."}, {"id": "D", "text": "Reef 4 had the fewest fish."}]'::jsonb, '{"type": "table", "caption": "Fish counted at four reef sites", "headers": ["Site", "Fish counted"], "rows": [["Reef 1", "86"], ["Reef 2", "64"], ["Reef 3", "102"], ["Reef 4", "71"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-020', 'C', ARRAY['C']::TEXT[], 'Reef 3''s 102 fish is the highest count, and 102 minus 64 is 38. The remaining choices misstate the ranking.', '{"A": "Reef 2 had 64 fish, the fewest of the four.", "B": "Reef 1 had 86 fish, fewer than reef 3''s 102.", "D": "Reef 2 had 64 fish, fewer than reef 4''s 71."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-021', 'HDSAT-RW-M13-INFO-021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A school nutrition office is reviewing how many lunches were served each day in one week.', 'Which choice most effectively uses data from the chart to describe the week?', '[{"id": "A", "text": "Wednesday served more lunches than Tuesday."}, {"id": "B", "text": "Monday served more lunches than Thursday."}, {"id": "C", "text": "Friday served the most lunches."}, {"id": "D", "text": "Thursday''s 470 lunches were the week''s high, 50 more than Monday''s."}]'::jsonb, '{"type": "bar_chart", "caption": "Lunches served by day", "x_label": "Day", "y_label": "Lunches", "series": [{"label": "Mon", "value": 420}, {"label": "Tue", "value": 455}, {"label": "Wed", "value": 390}, {"label": "Thu", "value": 470}, {"label": "Fri", "value": 380}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-021', 'D', ARRAY['D']::TEXT[], 'Thursday''s 470 is the tallest bar, and 470 minus 420 is 50. The other choices contradict the bars.', '{"C": "Friday''s 380 lunches are the fewest of the week.", "A": "Wednesday served 390, fewer than Tuesday''s 455.", "B": "Monday served 420, fewer than Thursday''s 470."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-022', 'HDSAT-RW-M13-INFO-022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'An air-quality monitor logged hourly readings of a pollution index on a still, sunny day. Higher values indicate worse air.', 'Which choice most effectively uses data from the graph to describe the day?', '[{"id": "A", "text": "The index peaked at 10 a.m."}, {"id": "B", "text": "The index peaked at noon at 78, then fell by 27 by 4 p.m."}, {"id": "C", "text": "The index rose steadily from morning through late afternoon."}, {"id": "D", "text": "The 8 a.m. reading was the day''s highest."}]'::jsonb, '{"type": "line_chart", "caption": "Pollution index readings by hour", "x_label": "Time", "y_label": "Index", "series": [{"label": "8 am", "value": 42}, {"label": "10 am", "value": 55}, {"label": "Noon", "value": 78}, {"label": "2 pm", "value": 66}, {"label": "4 pm", "value": 51}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-022', 'B', ARRAY['B']::TEXT[], 'The series reaches 78 at noon and falls to 51 at 4 p.m., a drop of 27. The other choices misdescribe the shape of the curve.', '{"C": "The index fell after noon, so it did not rise steadily all day.", "A": "The 10 a.m. reading of 55 is below the noon peak of 78.", "D": "The 8 a.m. reading of 42 is the lowest, not the highest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-023', 'HDSAT-RW-M13-INFO-023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A rail operator publishes the percentage of trains arriving on time for each of its four lines.', 'Which choice most effectively uses data from the table to compare the lines?', '[{"id": "A", "text": "Line 4 had the best record at 95%, 17 percentage points above line 3."}, {"id": "B", "text": "Line 2 had the lowest on-time rate."}, {"id": "C", "text": "Line 1 had the best on-time record."}, {"id": "D", "text": "Line 3 performed better than line 2."}]'::jsonb, '{"type": "table", "caption": "On-time arrivals by line", "headers": ["Line", "On-time (%)"], "rows": [["1", "92"], ["2", "86"], ["3", "78"], ["4", "95"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-023', 'A', ARRAY['A']::TEXT[], 'Line 4''s 95% is the highest rate, and 95 minus 78 is 17. The other choices reverse the ranking.', '{"C": "Line 1''s 92% is below line 4''s 95%.", "D": "Line 3''s 78% is below line 2''s 86%.", "B": "Line 3''s 78% is the lowest, not line 2''s 86%."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-024', 'HDSAT-RW-M13-INFO-024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A biology class measured one bean plant at the end of each of five weeks.', 'Which choice most effectively uses data from the chart to describe the plant''s growth?', '[{"id": "A", "text": "The plant reached 20 cm by week 3."}, {"id": "B", "text": "The plant''s height doubled between weeks 1 and 3."}, {"id": "C", "text": "The plant reached 20 cm by week 5, 14 cm taller than in week 1."}, {"id": "D", "text": "The plant grew 6 cm between weeks 4 and 5."}]'::jsonb, '{"type": "bar_chart", "caption": "Bean plant height at the end of each week", "x_label": "Week", "y_label": "Height (cm)", "series": [{"label": "1", "value": 6}, {"label": "2", "value": 9}, {"label": "3", "value": 13}, {"label": "4", "value": 18}, {"label": "5", "value": 20}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-024', 'C', ARRAY['C']::TEXT[], 'The plant measures 6 cm in week 1 and 20 cm in week 5, a difference of 14 cm. The other choices misread specific bars.', '{"A": "Week 3 shows 13 cm; 20 cm is the week 5 height.", "B": "Doubling 6 cm would give 12 cm, but week 3 shows 13 cm.", "D": "The plant grew from 18 cm to 20 cm between weeks 4 and 5, a gain of 2 cm."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-025', 'HDSAT-RW-M13-INFO-025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A consumer lab tested how long four portable batteries powered the same device on one charge.', 'Which choice most effectively uses data from the table to compare the batteries?', '[{"id": "A", "text": "Battery A lasted the longest of the four."}, {"id": "B", "text": "Battery D outlasted battery C."}, {"id": "C", "text": "Battery C lasted 9.4 hours, 2.6 hours longer than battery D."}, {"id": "D", "text": "Battery B outlasted battery A."}]'::jsonb, '{"type": "table", "caption": "Battery runtime under identical load (hours)", "headers": ["Battery", "Runtime (hours)"], "rows": [["A", "8.5"], ["B", "7.2"], ["C", "9.4"], ["D", "6.8"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-025', 'C', ARRAY['C']::TEXT[], 'Battery C''s 9.4 hours is the longest runtime, and 9.4 minus 6.8 is 2.6. The other statements contradict the table.', '{"A": "Battery A lasted 8.5 hours, less than battery C''s 9.4.", "D": "Battery B lasted 7.2 hours, less than battery A''s 8.5.", "B": "Battery D lasted the shortest time of all four."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-026', 'HDSAT-RW-M13-INFO-026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A volunteer network recorded the hours its members contributed each month.', 'Which choice most effectively uses data from the chart to describe the trend?', '[{"id": "A", "text": "February''s hours exceeded April''s."}, {"id": "B", "text": "March''s hours were double February''s."}, {"id": "C", "text": "January had the most volunteer hours."}, {"id": "D", "text": "April''s 240 hours were double January''s 120 hours."}]'::jsonb, '{"type": "bar_chart", "caption": "Volunteer hours by month", "x_label": "Month", "y_label": "Hours", "series": [{"label": "Jan", "value": 120}, {"label": "Feb", "value": 180}, {"label": "Mar", "value": 150}, {"label": "Apr", "value": 240}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-026', 'D', ARRAY['D']::TEXT[], 'April''s bar is 240 and January''s is 120, so April is exactly twice January. The other choices contradict the bars.', '{"B": "March recorded 150 hours, less than February''s 180, so it was not double.", "C": "January''s 120 hours are the fewest of the four months.", "A": "February recorded 180 hours, below April''s 240."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-027', 'HDSAT-RW-M13-INFO-027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A parks service reported annual visits to a state park over four years, in thousands.', 'Which choice most effectively uses data from the graph to summarize the four years?', '[{"id": "A", "text": "Visits reached their peak in 2021 at 21,000."}, {"id": "B", "text": "Visits were highest in 2022."}, {"id": "C", "text": "Visits in 2022 exceeded those in 2021."}, {"id": "D", "text": "Visits were highest in 2019."}]'::jsonb, '{"type": "line_chart", "caption": "Annual park visits (thousands)", "x_label": "Year", "y_label": "Visits (thousands)", "series": [{"label": "2019", "value": 12}, {"label": "2020", "value": 18}, {"label": "2021", "value": 21}, {"label": "2022", "value": 19}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-027', 'A', ARRAY['A']::TEXT[], 'The 2021 point sits highest at 21 thousand visits. The other choices contradict the plotted points.', '{"B": "2022 recorded 19,000 visits, fewer than 2021''s 21,000.", "D": "2019 recorded 12,000 visits, the lowest of the four years.", "C": "2022 recorded 19,000 visits, below 2021''s 21,000."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-028', 'HDSAT-RW-M13-INFO-028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A dairy co-op compared the yearly milk yield of three herds.', 'Which choice most effectively uses data from the table to compare the herds?', '[{"id": "A", "text": "Herd C produced the most milk."}, {"id": "B", "text": "Herd B produced 2,140 liters, 290 more than herd A."}, {"id": "C", "text": "Herd A produced more than herd C."}, {"id": "D", "text": "Herd B produced fewer than 2,000 liters."}]'::jsonb, '{"type": "table", "caption": "Milk yield by herd (liters per year)", "headers": ["Herd", "Yield (liters)"], "rows": [["A", "1,850"], ["B", "2,140"], ["C", "1,960"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-028', 'B', ARRAY['B']::TEXT[], 'Herd B''s 2,140 liters is the largest yield, and 2,140 minus 1,850 is 290. The other choices misstate the figures.', '{"A": "Herd C produced 1,960 liters, less than herd B''s 2,140.", "C": "Herd A produced 1,850 liters, less than herd C''s 1,960.", "D": "Herd B produced 2,140 liters, above 2,000."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-029', 'HDSAT-RW-M13-INFO-029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A forestry crew counted saplings in three restoration plots of the same size.', 'Which choice most effectively uses data from the table to compare the plots?', '[{"id": "A", "text": "Plot 2 held 310 saplings, 25 more than plot 3."}, {"id": "B", "text": "Plot 1 held the most saplings."}, {"id": "C", "text": "Plot 3 held more saplings than plot 2."}, {"id": "D", "text": "Plot 2 held fewer than 280 saplings."}]'::jsonb, '{"type": "table", "caption": "Saplings counted by plot", "headers": ["Plot", "Saplings"], "rows": [["1", "240"], ["2", "310"], ["3", "285"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-029', 'A', ARRAY['A']::TEXT[], 'Plot 2''s 310 saplings are the highest count, and 310 minus 285 is 25. The other choices contradict the table.', '{"B": "Plot 1 held 240 saplings, the fewest of the three.", "C": "Plot 3 held 285 saplings, fewer than plot 2''s 310.", "D": "Plot 2 held 310 saplings, above 280."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-030', 'HDSAT-RW-M13-INFO-030', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A clinic tracked the average wait time for walk-in patients on each weekday.', 'Which choice most effectively uses data from the chart to describe the week?', '[{"id": "A", "text": "Tuesday had the longest average wait."}, {"id": "B", "text": "Friday had the longest average wait."}, {"id": "C", "text": "Thursday''s wait of 55 minutes was the longest, 21 minutes more than Monday''s."}, {"id": "D", "text": "Wednesday had the shortest average wait."}]'::jsonb, '{"type": "bar_chart", "caption": "Average walk-in wait by weekday (minutes)", "x_label": "Day", "y_label": "Wait (minutes)", "series": [{"label": "Mon", "value": 34}, {"label": "Tue", "value": 48}, {"label": "Wed", "value": 41}, {"label": "Thu", "value": 55}, {"label": "Fri", "value": 38}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-030', 'C', ARRAY['C']::TEXT[], 'Thursday''s bar is the tallest at 55, and 55 minus 34 is 21. The other choices misidentify the extremes.', '{"A": "Tuesday''s wait was 48, below Thursday''s 55.", "B": "Friday''s wait was 38, below Thursday''s 55.", "D": "Monday''s 34 minutes is the shortest wait, not Wednesday''s 41."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-031', 'HDSAT-RW-M13-INFO-031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A media class logged the hours each member spent watching streaming video over four weeks.', 'Which choice most effectively uses data from the table to describe the four weeks?', '[{"id": "A", "text": "Week 3 had more hours than week 2."}, {"id": "B", "text": "Week 4 had the most hours, 9.5, which was 3 more than week 1."}, {"id": "C", "text": "Week 2 had the most hours."}, {"id": "D", "text": "Week 1 had the most hours."}]'::jsonb, '{"type": "table", "caption": "Streaming hours logged each week", "headers": ["Week", "Hours"], "rows": [["1", "6.5"], ["2", "8.0"], ["3", "7.0"], ["4", "9.5"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-031', 'B', ARRAY['B']::TEXT[], 'Week 4''s 9.5 hours are the highest figure, and 9.5 minus 6.5 is 3. The remaining choices contradict the table.', '{"C": "Week 2 logged 8.0 hours, fewer than week 4''s 9.5.", "A": "Week 3 logged 7.0 hours, fewer than week 2''s 8.0.", "D": "Week 1 logged 6.5 hours, the fewest of the four weeks."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-032', 'HDSAT-RW-M13-INFO-032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A running club recorded how many members finished its annual marathon over five years.', 'Which choice most effectively uses data from the graph to describe the five years?', '[{"id": "A", "text": "Finishers were lowest in 2020 at 210, 490 fewer than in 2022."}, {"id": "B", "text": "Finishers in 2020 were above the 2019 total."}, {"id": "C", "text": "Finishers were lowest in 2018."}, {"id": "D", "text": "Finishers were highest in 2021."}]'::jsonb, '{"type": "line_chart", "caption": "Marathon finishers by year", "x_label": "Year", "y_label": "Finishers", "series": [{"label": "2018", "value": 480}, {"label": "2019", "value": 560}, {"label": "2020", "value": 210}, {"label": "2021", "value": 640}, {"label": "2022", "value": 700}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-032', 'A', ARRAY['A']::TEXT[], 'The 2020 point is the lowest at 210, and 700 minus 210 is 490. The other choices contradict the series.', '{"C": "2018 recorded 480 finishers, above the 2020 low of 210.", "D": "2021 recorded 640 finishers, fewer than 2022''s 700.", "B": "2020 recorded 210 finishers, far below 2019''s 560."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-033', 'HDSAT-RW-M13-INFO-033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A municipal compost program weighed the material processed at three sites in one month.', 'Which choice most effectively uses data from the table to compare the sites?', '[{"id": "A", "text": "Site 1 processed the most material."}, {"id": "B", "text": "Site 2 processed 420 kg, 40 more than site 3."}, {"id": "C", "text": "Site 2 processed fewer than 400 kg."}, {"id": "D", "text": "Site 3 processed more than site 2."}]'::jsonb, '{"type": "table", "caption": "Compost processed by site (kg)", "headers": ["Site", "Weight (kg)"], "rows": [["1", "310"], ["2", "420"], ["3", "380"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-033', 'B', ARRAY['B']::TEXT[], 'Site 2''s 420 kg is the largest amount, and 420 minus 380 is 40. The other choices misstate the values.', '{"A": "Site 1 processed 310 kg, the least of the three.", "D": "Site 3 processed 380 kg, less than site 2''s 420.", "C": "Site 2 processed 420 kg, above 400."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-034', 'HDSAT-RW-M13-INFO-034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A ferry operator counted passengers on each of four morning crossings.', 'Which choice most effectively uses data from the chart to describe the morning?', '[{"id": "A", "text": "The 6 a.m. crossing carried more passengers than the noon crossing."}, {"id": "B", "text": "The noon crossing carried the most passengers."}, {"id": "C", "text": "The 8 a.m. crossing carried 260 passengers, 80 more than the 10 a.m. crossing."}, {"id": "D", "text": "The 10 a.m. crossing carried the most passengers."}]'::jsonb, '{"type": "bar_chart", "caption": "Passengers per crossing", "x_label": "Departure", "y_label": "Passengers", "series": [{"label": "6 am", "value": 120}, {"label": "8 am", "value": 260}, {"label": "10 am", "value": 180}, {"label": "Noon", "value": 140}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-034', 'C', ARRAY['C']::TEXT[], 'The 8 a.m. bar is the tallest at 260, and 260 minus 180 is 80. The other choices contradict the chart.', '{"D": "The 10 a.m. crossing carried 180, fewer than 260.", "B": "The noon crossing carried 140, the second fewest.", "A": "The 6 a.m. crossing carried 120, fewer than the noon crossing''s 140."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-035', 'HDSAT-RW-M13-INFO-035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'An orchard cooperative recorded the total harvest of three fruits in one season.', 'Which choice most effectively uses data from the table to compare the harvests?', '[{"id": "A", "text": "The apple harvest was below 1,000 kg."}, {"id": "B", "text": "The pear harvest was the largest."}, {"id": "C", "text": "The plum harvest exceeded the pear harvest."}, {"id": "D", "text": "The apple harvest was 1,240 kg, 380 more than the pear harvest."}]'::jsonb, '{"type": "table", "caption": "Harvest by fruit (kg)", "headers": ["Fruit", "Harvest (kg)"], "rows": [["Apple", "1,240"], ["Pear", "860"], ["Plum", "520"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-035', 'D', ARRAY['D']::TEXT[], 'The apple harvest is the largest at 1,240 kg, and 1,240 minus 860 is 380. The other choices contradict the table.', '{"B": "The pear harvest of 860 kg is below the apple harvest.", "C": "The plum harvest of 520 kg is below the pear harvest''s 860.", "A": "The apple harvest of 1,240 kg is above 1,000."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-036', 'HDSAT-RW-M13-INFO-036', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A city forestry office measured the share of ground shaded by street trees every five years.', 'Which choice most effectively uses data from the graph to describe the change over twenty years?', '[{"id": "A", "text": "Canopy cover grew from 18% to 34%, an increase of 16 percentage points."}, {"id": "B", "text": "Canopy cover fell after 2010."}, {"id": "C", "text": "Canopy cover was highest in 2005."}, {"id": "D", "text": "Canopy cover doubled between 2000 and 2020."}]'::jsonb, '{"type": "line_chart", "caption": "Street-tree canopy cover by year", "x_label": "Year", "y_label": "Canopy cover (%)", "series": [{"label": "2000", "value": 18}, {"label": "2005", "value": 22}, {"label": "2010", "value": 27}, {"label": "2015", "value": 31}, {"label": "2020", "value": 34}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-036', 'A', ARRAY['A']::TEXT[], 'The series runs from 18 to 34, a gain of 16 points. Doubling 18 would give 36, which the series never reaches, and the later points keep rising.', '{"D": "Doubling 18% would be 36%, but the 2020 figure is 34%.", "B": "Cover rose from 27% in 2010 to 34% in 2020.", "C": "2005 recorded 22%, below every later survey."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-037', 'HDSAT-RW-M13-INFO-037', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A school coding club recorded its membership at the end of each month in the fall.', 'Which choice most effectively uses data from the table to describe membership?', '[{"id": "A", "text": "October had more members than November."}, {"id": "B", "text": "Membership was highest in September."}, {"id": "C", "text": "Membership was highest in December."}, {"id": "D", "text": "Membership peaked in November at 23, two more than in December."}]'::jsonb, '{"type": "table", "caption": "Coding club members by month", "headers": ["Month", "Members"], "rows": [["September", "14"], ["October", "19"], ["November", "23"], ["December", "21"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-037', 'D', ARRAY['D']::TEXT[], 'November''s 23 members are the most recorded, and 23 minus 21 is 2. The other choices misstate the peak.', '{"C": "December had 21 members, below November''s 23.", "B": "September had 14 members, the fewest of the four months.", "A": "October had 19 members, fewer than November''s 23."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-038', 'HDSAT-RW-M13-INFO-038', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A bicycle repair workshop logged the number of jobs completed on each of four days.', 'Which choice most effectively uses data from the table to describe the four days?', '[{"id": "A", "text": "Wednesday''s 12 jobs were the most, five more than Monday''s."}, {"id": "B", "text": "Thursday completed the most jobs."}, {"id": "C", "text": "Tuesday completed the most jobs."}, {"id": "D", "text": "Wednesday completed fewer jobs than Tuesday."}]'::jsonb, '{"type": "table", "caption": "Repair jobs completed by day", "headers": ["Day", "Jobs"], "rows": [["Monday", "7"], ["Tuesday", "9"], ["Wednesday", "12"], ["Thursday", "8"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-038', 'A', ARRAY['A']::TEXT[], 'Wednesday''s 12 jobs are the highest count, and 12 minus 7 is 5. The other choices contradict the table.', '{"C": "Tuesday completed 9 jobs, fewer than Wednesday''s 12.", "B": "Thursday completed 8 jobs, fewer than Wednesday''s 12.", "D": "Wednesday completed 12 jobs, more than Tuesday''s 9."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-039', 'HDSAT-RW-M13-INFO-039', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A community foundation counted grant applications in four categories.', 'Which choice most effectively uses data from the chart to compare the categories?', '[{"id": "A", "text": "Arts received more applications than education."}, {"id": "B", "text": "Environment received the most applications."}, {"id": "C", "text": "Health received the most applications."}, {"id": "D", "text": "Education received 52 applications, 24 more than environment."}]'::jsonb, '{"type": "bar_chart", "caption": "Grant applications by category", "x_label": "Category", "y_label": "Applications", "series": [{"label": "Arts", "value": 34}, {"label": "Health", "value": 46}, {"label": "Education", "value": 52}, {"label": "Environment", "value": 28}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-039', 'D', ARRAY['D']::TEXT[], 'Education''s 52 applications are the most, and 52 minus 28 is 24. The other choices contradict the bars.', '{"C": "Health received 46 applications, fewer than education''s 52.", "B": "Environment received 28 applications, the fewest of the four.", "A": "Arts received 34 applications, fewer than education''s 52."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-040', 'HDSAT-RW-M13-INFO-040', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'An ecology class measured water temperature in a stream once per season.', 'Which choice most effectively uses data from the table to compare the seasons?', '[{"id": "A", "text": "Summer water was 19 C, 8 degrees warmer than spring water."}, {"id": "B", "text": "Winter was the warmest season."}, {"id": "C", "text": "Fall was the warmest season."}, {"id": "D", "text": "Spring water was warmer than summer water."}]'::jsonb, '{"type": "table", "caption": "Stream temperature by season", "headers": ["Season", "Temperature (C)"], "rows": [["Spring", "11"], ["Summer", "19"], ["Fall", "14"], ["Winter", "6"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-040', 'A', ARRAY['A']::TEXT[], 'Summer''s 19 C is the highest reading, and 19 minus 11 is 8. The other choices reverse the ranking.', '{"C": "Fall measured 14 C, below summer''s 19 C.", "B": "Winter measured 6 C, the coldest reading.", "D": "Spring measured 11 C, below summer''s 19 C."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-041', 'HDSAT-RW-M13-INFO-041', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In a coastal estuary, conservation crews installed low fences of woven branches along the edge of a tidal marsh. The fences slow incoming water just enough for suspended sediment to settle. Within three seasons the marsh surface had risen several centimeters, keeping pace with the local rise in sea level. Crews now treat the fences as temporary scaffolding: once grasses anchor the new sediment, the structures rot away.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A modest intervention can help a marsh build elevation fast enough to keep up with rising water."}, {"id": "B", "text": "Suspended sediment is unimportant to the health of a marsh."}, {"id": "C", "text": "Grasses grow faster than sea level rises in every estuary."}, {"id": "D", "text": "Woven fences are the only way to restore a coastal marsh."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-041', 'A', ARRAY['A']::TEXT[], 'The passage describes a low-cost fence that traps sediment, raises the marsh surface, and lets grasses take over. That makes a modest intervention the central point.', '{"D": "The text presents one technique, not a claim of exclusivity.", "C": "The passage describes one estuary keeping pace, not every estuary.", "B": "The entire mechanism depends on trapped sediment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-042', 'HDSAT-RW-M13-INFO-042', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'When a county archive began recording oral histories of retired dockworkers, staff wrote the summaries themselves. The transcripts were accurate but flat, stripped of the jokes and nicknames that carried meaning for the speakers. The archive then invited community members to annotate the recordings. Those notes identified people, places, and turns of phrase that outsiders had missed, and later researchers relied on them heavily.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The archive''s original transcripts contained factual errors."}, {"id": "B", "text": "Inviting community members to annotate recordings improved the archive''s records in ways staff alone could not."}, {"id": "C", "text": "Later researchers ignored the archive''s annotations."}, {"id": "D", "text": "Oral histories should replace written documents in county archives."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-042', 'B', ARRAY['B']::TEXT[], 'The passage says the staff transcripts were accurate but missed local meaning, and that community notes supplied what outsiders had missed. That is the central claim.', '{"A": "The text calls the transcripts accurate, not wrong.", "D": "No comparison with written documents is made.", "C": "The text says researchers relied on the notes heavily."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-043', 'HDSAT-RW-M13-INFO-043', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Paper mills in one region experimented with fibers from an invasive reed that clogs waterways. The reed broke down into pulp with less energy than wood, and the resulting paper was sturdy enough for packaging. Mills still cannot use the reed for fine writing paper because its fibers are short. Even so, harvesting the reed for packaging both lowered the cost of clearing waterways and produced a saleable product.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Using an invasive reed for packaging can yield a useful product while helping control the plant."}, {"id": "B", "text": "Short fibers make a paper stronger than long fibers do."}, {"id": "C", "text": "Mills have stopped clearing waterways because of the reed."}, {"id": "D", "text": "Invasive reeds are suitable for every kind of paper product."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-043', 'A', ARRAY['A']::TEXT[], 'The passage sets out one limitation, fine paper, and then states the double benefit of using the reed for packaging. The main idea is that practical use and control can go together.', '{"D": "The text explicitly says the reed cannot be used for fine writing paper.", "C": "Harvesting the reed lowered clearing costs rather than stopping the work.", "B": "The passage treats short fibers as the reason fine paper is impossible."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-044', 'HDSAT-RW-M13-INFO-044', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Biologists tracking foxes in a large city found that animals living near busy roads shifted most of their activity to the hours after midnight. In quieter neighborhoods, the same species remained active at dusk. The shift did not follow temperature or food availability, both of which were similar across the sites studied.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Foxes avoid cities entirely when roads are busy."}, {"id": "B", "text": "Foxes living near heavy traffic appear to adjust when they are active."}, {"id": "C", "text": "Food availability explains the difference between the sites."}, {"id": "D", "text": "Temperature determines when foxes leave their dens."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-044', 'B', ARRAY['B']::TEXT[], 'The passage reports a timing difference that tracks road traffic and rules out temperature and food. The central point is that the animals shift their active hours.', '{"A": "The foxes were living in the city, not avoiding it.", "D": "The text says temperature was similar across sites and did not explain the shift.", "C": "Food availability was also similar and is explicitly ruled out."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-045', 'HDSAT-RW-M13-INFO-045', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'A poet working in a signed language composes by filming sequences rather than writing lines. Rhymes in this poetry are formed by repeating handshapes or locations in space, and a single sign can be held to mark a pause. Readers of a printed gloss often miss these patterns because the notation records words, not movement.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Signed poetry does not use rhyme of any kind."}, {"id": "B", "text": "The visual structure of signed poetry is lost when the work is transcribed as words."}, {"id": "C", "text": "Poets who sign avoid filming their work."}, {"id": "D", "text": "Printed glosses make signed poems easier to understand."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-045', 'B', ARRAY['B']::TEXT[], 'The passage explains that rhyme lives in handshapes and held signs, which word-based notation does not capture. That is the central observation about transcription.', '{"A": "The text describes rhyme formed by repeated handshapes and locations.", "D": "It says readers of printed glosses often miss the patterns.", "C": "The poet composes by filming sequences."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-046', 'HDSAT-RW-M13-INFO-046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Chemists analyzed trace elements in glass beads from several ancient ports. Beads from one harbor shared a chemical signature with sand from a river hundreds of kilometers inland, while beads from a neighboring harbor matched a coastal source. The pattern suggests that finished beads moved along routes separate from those that carried raw materials.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Glassmaking began at the coast and spread inland."}, {"id": "B", "text": "Chemical signatures in the beads suggest that trade in finished goods followed different routes from trade in raw materials."}, {"id": "C", "text": "All of the beads were made from a single source of sand."}, {"id": "D", "text": "The harbors were abandoned once the beads arrived."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-046', 'B', ARRAY['B']::TEXT[], 'The beads match sources that do not match their own harbors, and the passage draws exactly that conclusion about separate routes. The other choices go beyond or contradict the evidence.', '{"C": "Two distinct source signatures are described.", "A": "The passage says nothing about where glassmaking began.", "D": "No claim is made about the harbors being abandoned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-047', 'HDSAT-RW-M13-INFO-047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A seed bank is often imagined as a freezer full of envelopes. In practice, staff test germination every few years, because viability falls at different rates for different species. A batch that still sprouts at 80 percent may be left alone; one that falls below a threshold is regrown in a nursery so fresh seed can be stored.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All species lose viability at the same rate."}, {"id": "B", "text": "Freezers destroy the seeds they are meant to protect."}, {"id": "C", "text": "Seed banks store only seeds of food crops."}, {"id": "D", "text": "Maintaining a seed bank requires ongoing testing and renewal, not just storage."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-047', 'D', ARRAY['D']::TEXT[], 'The passage contrasts the freezer image with the regular testing and nursery regrowth that keep a collection alive. That contrast is the main idea.', '{"B": "Freezing is not described as harmful, only as insufficient on its own.", "A": "The text says viability falls at different rates for different species.", "C": "The passage never limits seed banks to food crops."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-048', 'HDSAT-RW-M13-INFO-048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Keepers of coastal lighthouses recorded weather every few hours for decades, noting wind, fog, and ice in bound volumes. Historians once treated these logs as background color. Climate scientists now digitize them, because the entries predate most instrumental records and describe conditions at headlands that no weather station covered.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The logs are valuable mainly for their descriptions of shipwrecks."}, {"id": "B", "text": "Routine records kept for one purpose can become valuable evidence for another."}, {"id": "C", "text": "Lighthouse keepers were trained as climate scientists."}, {"id": "D", "text": "Continuous instrumental records are older than the logs."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-048', 'B', ARRAY['B']::TEXT[], 'The logs were routine weather notes for lighthouse work and are now a climate data source. That change in use is the passage''s central point.', '{"C": "No such training is mentioned; the logs were simply kept routinely.", "D": "The text says the logs predate most instrumental records.", "A": "Shipwrecks are not mentioned at all."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-049', 'HDSAT-RW-M13-INFO-049', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'In a rehearsal, a quartet stopped midway through a piece. Instead of naming a chord, the pianist hummed a phrase and tapped the ride cymbal. The bassist nodded, and the group restarted with a different feel. Later, the musicians said they rarely discuss harmony in words; the sound itself carries the instruction.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The pianist is the group''s formal director."}, {"id": "B", "text": "The quartet avoids rehearsing altogether."}, {"id": "C", "text": "The bassist misunderstood the pianist''s cue."}, {"id": "D", "text": "The musicians often communicate musical changes through sound rather than verbal explanation."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-049', 'D', ARRAY['D']::TEXT[], 'The pianist conveys a change by humming and tapping, and the musicians say words are rarely needed. That is the central idea about how they communicate.', '{"B": "The passage shows a rehearsal in progress.", "A": "Nothing in the text establishes a formal director.", "C": "The bassist nods and the group restarts successfully."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-050', 'HDSAT-RW-M13-INFO-050', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Drilling an ice core yields a cylinder of layered snow. Each summer layer carries dust blown from continents, and the amount varies with wind strength and storm frequency. By counting layers and measuring dust, researchers reconstruct centuries of atmospheric circulation, even though no one recorded the weather at the time.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Ice cores record only the temperature of past summers."}, {"id": "B", "text": "Dust in ice-core layers provides a record of past atmospheric circulation."}, {"id": "C", "text": "All dust in an ice core comes from the ocean."}, {"id": "D", "text": "The layers cannot be counted reliably."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-050', 'B', ARRAY['B']::TEXT[], 'The passage explains how counted layers and measured dust reveal past winds even without written records. That reconstruction is the main idea.', '{"A": "The text focuses on dust and circulation, not only summer temperature.", "C": "It says the dust was blown from continents.", "D": "Layer counting is the method the researchers rely on."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-051', 'HDSAT-RW-M13-INFO-051', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A weaving cooperative began attaching a small tag to each blanket naming the weaver and the pattern''s origin. Buyers had previously chosen by color alone. After the tags appeared, orders shifted toward patterns whose stories customers could read, and younger weavers began learning designs that had nearly gone unused.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Buyers preferred blankets with no visible pattern."}, {"id": "B", "text": "Older weavers stopped teaching their designs."}, {"id": "C", "text": "The tags caused prices to fall sharply."}, {"id": "D", "text": "Sharing the story behind a pattern changed which designs buyers chose and renewed interest in them."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-051', 'D', ARRAY['D']::TEXT[], 'The passage links the tags to a shift in orders and to younger weavers learning neglected designs. That is the central point about visible provenance.', '{"A": "Orders shifted toward patterned work with stories attached.", "C": "Prices are never mentioned.", "B": "Younger weavers began learning designs that had gone unused."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-052', 'HDSAT-RW-M13-INFO-052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'A historian compared two sixteenth-century maps of the same coastline. One shows a wide estuary; the other omits it and places a headland in its stead. The historian argues that the second map was copied from the first but corrected using a sailor''s sketch, which recorded the headland after a storm had closed the estuary mouth.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The maps'' disagreement may reflect a real change in the coastline rather than a copying error."}, {"id": "B", "text": "The estuary never existed and was invented by a mapmaker."}, {"id": "C", "text": "Both maps were drawn from the same survey."}, {"id": "D", "text": "The second map is simply a careless copy of the first."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-052', 'A', ARRAY['A']::TEXT[], 'The historian''s argument is that the coastline itself changed between surveys, so both maps can be right. That is the passage''s central claim.', '{"C": "The text says the second map was corrected from a different sketch.", "B": "The estuary appears on the earlier map and is described as having been closed by a storm.", "D": "The passage argues against treating the difference as an error."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-053', 'HDSAT-RW-M13-INFO-053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Hives kept on city rooftops often produce as much honey as hives in surrounding farmland. The reason seems to be variety: parks, balconies, and vacant lots supply flowers in succession from spring to fall, while a single field may bloom for only a few weeks. Beekeepers who plant for continuous bloom report steadier yields.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A range of flowers available over a long season can support urban hives."}, {"id": "B", "text": "Farmland has no bees at all."}, {"id": "C", "text": "Urban honey always tastes better than farm honey."}, {"id": "D", "text": "Rooftop hives need less care than rural hives."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-053', 'A', ARRAY['A']::TEXT[], 'The passage attributes urban yields to flowers blooming in succession across many small spaces. That variety is the main explanation offered.', '{"C": "Taste is not discussed.", "B": "Farmland is described as having fields that bloom briefly, not as lacking bees.", "D": "The amount of care is never compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-054', 'HDSAT-RW-M13-INFO-054', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'When a small theater replaced its incandescent fixtures with LEDs, rehearsals changed. Actors could suddenly see the audience, and directors began blocking movement that used the whole stage rather than the lit center. The lighting designer noted that the new fixtures, though brighter, required careful dimming to preserve the shadows the company relied on.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Audiences objected to the new lighting."}, {"id": "B", "text": "The theater removed all shadows from its stage."}, {"id": "C", "text": "The new fixtures were dimmer than the old ones."}, {"id": "D", "text": "A change in lighting technology altered how the company staged its performances."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-054', 'D', ARRAY['D']::TEXT[], 'The passage connects the new fixtures to changes in blocking and to the designer''s adjusted approach. The main idea is that the technology reshaped the staging.', '{"C": "The text calls the new fixtures brighter.", "B": "The designer worked to preserve shadows rather than eliminate them.", "A": "Audience reaction is not described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-055', 'HDSAT-RW-M13-INFO-055', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Before industrial whaling, sailors recorded whale sightings in logbooks, often noting only that whales were numerous. Researchers combing these logs found that sightings clustered along particular currents. The clustering matches modern tracking of the whales'' prey, suggesting the animals followed food rather than fixed migration routes.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Whales no longer migrate at all."}, {"id": "B", "text": "The logs prove that whaling caused the population to decline."}, {"id": "C", "text": "Sailors exaggerated the number of whales they saw."}, {"id": "D", "text": "Old sighting records suggest that whale movements followed food rather than a fixed route."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-055', 'D', ARRAY['D']::TEXT[], 'The passage reports that sightings match the location of prey and draws a conclusion about food rather than fixed routes. That conclusion is the main idea.', '{"C": "The text treats the logs as usable evidence, not as exaggeration.", "A": "It describes movement patterns, not an end to migration.", "B": "Population decline is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-056', 'HDSAT-RW-M13-INFO-056', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Seedlings grown in sterilized soil often wilt during a dry spell, while seedlings in soil containing mycorrhizal fungi keep growing. The fungi extend threadlike networks that reach water beyond the plant''s roots, and they receive sugars in return. In a drought year, plots with intact fungal networks produced more saplings than plots where the soil had been turned.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Saplings in disturbed plots grew more than those in intact plots."}, {"id": "B", "text": "Mycorrhizal fungi harm the seedlings they associate with."}, {"id": "C", "text": "Fungal networks can help seedlings survive drought by extending their access to water."}, {"id": "D", "text": "Sterilizing soil improves seedling growth in dry conditions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-056', 'C', ARRAY['C']::TEXT[], 'The passage explains that fungal threads reach water the roots cannot and reports better sapling survival where the networks were intact. That is the main claim.', '{"B": "The relationship is described as mutually beneficial.", "D": "Sterilized soil seedlings wilted, so sterilization did not improve growth.", "A": "Intact plots produced more saplings than disturbed plots."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-057', 'HDSAT-RW-M13-INFO-057', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Moths of one species rest on tree bark and range from pale to dark. In a forest where soot darkened the trunks, dark moths became more common over several decades. When air-quality rules later lightened the trunks, pale moths increased again. These shifts suggest that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "individual moths changed color as the bark darkened."}, {"id": "B", "text": "soot helped the moths find food more easily."}, {"id": "C", "text": "the species split into two separate populations."}, {"id": "D", "text": "moths whose color contrasted with the bark were more likely to be caught by birds."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-057', 'D', ARRAY['D']::TEXT[], 'The population shifts track how well each color matches the bark, which points to visual predators selecting the conspicuous moths. The other options require mechanisms the passage does not support.', '{"A": "An individual moth cannot change its inherited color as bark darkens.", "B": "The passage is about camouflage, not food finding.", "C": "No splitting of the species is described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-058', 'HDSAT-RW-M13-INFO-058', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In a greenhouse, seedlings planted in soil from an old meadow grew larger than seedlings in soil from a young lawn, even though both soils had the same nutrients and water. When the meadow soil was heated to kill microbes, its advantage disappeared. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "meadow plants grow faster than lawn plants in every soil."}, {"id": "B", "text": "microorganisms in the meadow soil contributed to the seedlings'' greater growth."}, {"id": "C", "text": "lawn soil cannot support seedlings under any conditions."}, {"id": "D", "text": "heating the soil added nutrients that the lawn soil lacked."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-058', 'B', ARRAY['B']::TEXT[], 'Because nutrients and water were equal, and killing microbes removed the advantage, the living organisms in the meadow soil are the remaining explanation.', '{"D": "Heating removed the advantage rather than creating one.", "C": "Lawn soil supported seedlings; they simply grew less.", "A": "The comparison is between soils, not between plant types."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-059', 'HDSAT-RW-M13-INFO-059', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Chemical residue inside cooking pots from a coastal settlement contained fats from both land animals and fish. The pots were found in households of similar size and age. This pattern suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the settlement had no access to land animals."}, {"id": "B", "text": "fish were traded inland from the settlement."}, {"id": "C", "text": "the pots were used only for storage."}, {"id": "D", "text": "the households used a mix of land and marine foods rather than specializing in one."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-059', 'D', ARRAY['D']::TEXT[], 'Pots in comparable households held both kinds of fat, which points to mixed use rather than specialization. The other choices contradict the residue or add unsupported claims.', '{"A": "Land-animal fats were found, so the settlement did have access to them.", "B": "Trade is not mentioned in the passage.", "C": "The pots were used for cooking, as the residue shows."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-060', 'HDSAT-RW-M13-INFO-060', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Young birds of one species raised in isolation develop songs that lack the local dialect heard in the wild. When recordings of the dialect are played to them during a sensitive period, their songs come to match it. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "isolation improves the accuracy of a bird''s song."}, {"id": "B", "text": "young birds learn dialect features from what they hear rather than from instinct alone."}, {"id": "C", "text": "dialects are inherited genetically from parents."}, {"id": "D", "text": "adult birds can no longer learn new songs."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-060', 'B', ARRAY['B']::TEXT[], 'Isolated birds lacked the dialect, and hearing recordings restored it, which shows a learned component. That rules out a purely genetic explanation.', '{"C": "Inherited song would not depend on hearing recordings.", "D": "The study concerns young birds, not adult learning.", "A": "Isolated songs lacked the local dialect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-061', 'HDSAT-RW-M13-INFO-061', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A northern community builds a road across a frozen lake each winter. Officials close the road when measured ice thickness falls below a set level, even if the surface looks solid. This policy assumes that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "drivers can judge ice thickness reliably by looking at it."}, {"id": "B", "text": "visible surface conditions can hide ice too thin to support vehicles."}, {"id": "C", "text": "thick ice never melts during the winter."}, {"id": "D", "text": "the road is used only during daylight hours."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-061', 'B', ARRAY['B']::TEXT[], 'Closing the road despite a solid-looking surface implies that appearance is not a safe guide. That is the assumption behind measuring thickness.', '{"C": "No claim is made that ice never melts.", "A": "The policy exists precisely because looking is not enough.", "D": "The timing of use is not mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-062', 'HDSAT-RW-M13-INFO-062', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Gardeners in a neighborhood with older housing tested their soil and found elevated lead near building foundations. They moved vegetable beds away from the walls and added clean compost. Subsequent tests showed lower lead in the beds. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "compost removes lead from the vegetables that grow in it."}, {"id": "B", "text": "the first tests were performed incorrectly."}, {"id": "C", "text": "the beds'' location and added soil, rather than the neighborhood as a whole, explained the earlier readings."}, {"id": "D", "text": "lead occurs naturally throughout the neighborhood''s soil."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-062', 'C', ARRAY['C']::TEXT[], 'Lead was elevated only near foundations, and moving the beds plus adding clean soil lowered the readings, which points to local conditions rather than a neighborhood-wide problem.', '{"A": "The passage does not claim compost removes lead from plants.", "D": "The pattern near foundations suggests a local source, not a uniform natural level.", "B": "The change after relocating the beds supports the original tests rather than discrediting them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-063', 'HDSAT-RW-M13-INFO-063', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Documents stored in a damp basement faded more than identical documents stored in a dry room. The ink in both sets was made from the same recipe. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "moisture accelerated the fading of the ink."}, {"id": "B", "text": "the basement documents were much older."}, {"id": "C", "text": "the ink recipe changed between the two sets."}, {"id": "D", "text": "light alone caused all of the fading."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-063', 'A', ARRAY['A']::TEXT[], 'The documents and ink were the same, so the storage condition is the difference that explains the extra fading. Moisture is the only variable named.', '{"B": "Nothing indicates an age difference.", "C": "The passage says both sets used the same recipe.", "D": "Light conditions are not described as differing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-064', 'HDSAT-RW-M13-INFO-064', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Lichen species differ in how much air pollution they tolerate. Surveys along a road found only tolerant species near the highway and a mix of tolerant and sensitive species farther away. This pattern suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "tolerant species require polluted air to survive."}, {"id": "B", "text": "pollution levels decline with distance from the highway."}, {"id": "C", "text": "sensitive species prefer the soil beside roads."}, {"id": "D", "text": "lichens move quickly from one site to another."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-064', 'B', ARRAY['B']::TEXT[], 'Sensitive lichens appear only where pollution is lower, which implies a gradient away from the road. That is the inference the survey supports.', '{"C": "Sensitive species were absent near the road, the opposite of preferring it.", "A": "Tolerance does not mean a requirement for pollution.", "D": "Dispersal speed is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-065', 'HDSAT-RW-M13-INFO-065', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'A shoreline behind an oyster reef eroded less than a nearby shoreline without one. Waves reaching the first shore were measured as smaller. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the reef reduced wave energy before the waves reached the shore."}, {"id": "B", "text": "oysters cement loose sand into solid rock."}, {"id": "C", "text": "the second shoreline had softer soil."}, {"id": "D", "text": "erosion depends only on the height of the tide."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-065', 'A', ARRAY['A']::TEXT[], 'Smaller waves arrived where the reef stood, and that shore eroded less, which points to the reef absorbing wave energy.', '{"B": "No cementing process is described.", "C": "Soil differences are not mentioned.", "D": "The comparison isolates the presence of the reef."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-066', 'HDSAT-RW-M13-INFO-066', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Bats of one species forage along unlit paths more than along paths lit all night. When lamps were fitted with shields that directed light downward, bat activity along those paths increased. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "bats avoid every kind of artificial light equally."}, {"id": "B", "text": "the bats changed their diet after the shields were added."}, {"id": "C", "text": "light spilling sideways, not light itself, discouraged the bats."}, {"id": "D", "text": "shields attracted more insects to the paths."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-066', 'C', ARRAY['C']::TEXT[], 'The lamps still shone, but shielding the sideways spill restored activity, so the direction of the light mattered. That isolates spill rather than light in general.', '{"A": "The shielded paths were still lit and the bats returned.", "D": "Insect numbers are not measured in the passage.", "B": "Diet is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-067', 'HDSAT-RW-M13-INFO-067', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Pressed specimens of one wildflower, collected over a century at the same site and stored identically, show earlier flowering dates in recent decades. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the collectors visited the site only in spring."}, {"id": "B", "text": "the plants have been flowering earlier than they did a century ago."}, {"id": "C", "text": "pressing the flowers altered the dates on the labels."}, {"id": "D", "text": "the species has stopped flowering at this site."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-067', 'B', ARRAY['B']::TEXT[], 'With the site and storage held constant, the shift in recorded dates points to a real change in flowering time. That is the inference the evidence supports.', '{"A": "A spring-only collector could not produce the range of dates described.", "C": "Pressing does not change the collection date on a label.", "D": "The specimens document flowering, which continues."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-068', 'HDSAT-RW-M13-INFO-068', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Seeds of a shrub germinate readily after being heated to temperatures reached in a brush fire but rarely without heat. In unburned plots seedlings are scarce; in recently burned plots they are abundant. This suggests that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "fire supplies all the nutrients the shrub needs."}, {"id": "B", "text": "the shrub requires deep shade to reproduce."}, {"id": "C", "text": "fire cues trigger germination in this species."}, {"id": "D", "text": "heat kills most of the shrub''s seeds."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-068', 'C', ARRAY['C']::TEXT[], 'Seeds sprout after heat and seedlings follow fire, which indicates that fire acts as a germination cue. The other choices contradict the observation.', '{"A": "Nutrients are not measured in the passage.", "D": "Heated seeds germinated readily rather than dying.", "B": "Seedlings were abundant in burned, open plots."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-069', 'HDSAT-RW-M13-INFO-069', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A repair cafe invites volunteers to fix broken appliances for free. A city report opens by describing the tons of small electronics discarded each year. It then describes a weekend cafe where volunteers repaired 60 of the 75 items brought in. The report concludes that repair events divert only a fraction of the waste stream but build skills that outlast the events.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a repair process step by step in chronological order."}, {"id": "B", "text": "It argues that volunteers are responsible for electronic waste."}, {"id": "C", "text": "It compares two cities that run repair cafes."}, {"id": "D", "text": "It frames a large problem, presents a small-scale response to it, then qualifies that response''s impact."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-069', 'D', ARRAY['D']::TEXT[], 'The report moves from the scale of the waste problem to one event and then limits the claim while noting another benefit. That is the structure described.', '{"C": "Only one city''s report is described.", "B": "The report credits volunteers with repairs, not with creating the waste.", "A": "The passage describes the report''s parts, not a repair procedure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-070', 'HDSAT-RW-M13-INFO-070', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'For years researchers assumed that sleep simply rested the brain. A study then showed that participants who slept after learning a list recalled more words than those who stayed awake. A second study found that the benefit depended on deep sleep rather than total hours. Together the studies shifted the question from whether sleep matters to which stage does the work.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two theories and concludes that neither can be tested."}, {"id": "B", "text": "It traces a shift from a general assumption to a more specific research question."}, {"id": "C", "text": "It offers practical advice for improving sleep."}, {"id": "D", "text": "It describes a single experiment in exhaustive detail."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-070', 'B', ARRAY['B']::TEXT[], 'The passage starts with an old assumption, reports two studies, and ends by naming a narrower question. That progression is the structure.', '{"D": "Two studies are summarized briefly, not one in detail.", "A": "The research is described as testable and productive.", "C": "No advice about sleep habits is given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-071', 'HDSAT-RW-M13-INFO-071', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Early maps of a river delta show channels that no longer exist. A later map, drawn after a flood, shows a single channel. The text notes that the earlier channels were not errors: the delta itself had changed between surveys.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains why two maps that appear to disagree can both be accurate."}, {"id": "B", "text": "It argues that one of the maps is a deliberate fraud."}, {"id": "C", "text": "It describes the printing techniques used to make maps."}, {"id": "D", "text": "It compares the colors used by two mapmakers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-071', 'A', ARRAY['A']::TEXT[], 'The text reconciles the two maps by explaining that the landscape changed, so the apparent disagreement is not an error. That reconciliation is its structure and purpose.', '{"B": "The text explicitly says the earlier channels were not errors.", "C": "Printing methods are not mentioned.", "D": "Color is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-072', 'HDSAT-RW-M13-INFO-072', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Many people assume that fermentation is a form of spoilage. The passage explains that in fermentation specific microbes outcompete the organisms that cause rot, and that the resulting acidity preserves food. It then notes that the same process can fail when temperatures favor the wrong microbes.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It corrects a common misconception and then notes a condition under which the process fails."}, {"id": "B", "text": "It gives a history of fermentation techniques."}, {"id": "C", "text": "It compares two recipes for the same food."}, {"id": "D", "text": "It argues that fermentation is unsafe in all cases."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-072', 'A', ARRAY['A']::TEXT[], 'The passage first separates fermentation from rot and then adds a failure condition. That correction-then-qualification sequence is the structure.', '{"B": "No historical development is traced.", "C": "Recipes are not compared.", "D": "The passage presents fermentation as a preserving process, not an unsafe one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-073', 'HDSAT-RW-M13-INFO-073', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'One museum labels objects with dates and materials only. Another writes labels that begin with a question and end with an unresolved detail. The passage describes visitors spending longer at the second museum''s cases and argues that the difference lies less in the objects than in the invitation to look closely.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It contrasts two labeling approaches and attributes a difference in visitor behavior to that contrast."}, {"id": "B", "text": "It compares the ticket prices of two museums."}, {"id": "C", "text": "It argues that museums should remove labels entirely."}, {"id": "D", "text": "It describes a single exhibit in detail."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-073', 'A', ARRAY['A']::TEXT[], 'The passage sets one labeling style against another and explains the difference in attention by that contrast. That comparison-and-attribution is the structure.', '{"C": "The passage discusses two kinds of labels, not their removal.", "D": "No single exhibit is described in detail.", "B": "Ticket prices are not mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-074', 'HDSAT-RW-M13-INFO-074', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The passage lists the benefits of street trees: shade, cooler air, and slower storm runoff. It then observes that trees planted in narrow pits often die within a decade, and that cities which count only initial plantings overstate their progress.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two species of street tree."}, {"id": "B", "text": "It argues that street trees are not worth planting."}, {"id": "C", "text": "It presents benefits and then qualifies a common way of measuring success."}, {"id": "D", "text": "It gives step-by-step planting instructions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-074', 'C', ARRAY['C']::TEXT[], 'After listing advantages, the passage points out that counting plantings alone can exaggerate progress. That is a qualification of a success measure.', '{"B": "The passage supports planting while questioning how progress is counted.", "A": "No species comparison is made.", "D": "No planting instructions are given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-075', 'HDSAT-RW-M13-INFO-075', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The passage opens with a clerk in 1908 who blamed a jammed typewriter for a missed deadline. It then widens out: manufacturers soon standardized keyboard layouts, and the standard outlasted the machines themselves.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It begins with a specific incident and uses it to introduce a broader development."}, {"id": "B", "text": "It describes how typewriters were manufactured."}, {"id": "C", "text": "It compares two offices in different countries."}, {"id": "D", "text": "It argues that the clerk was correct about the cause of the delay."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-075', 'A', ARRAY['A']::TEXT[], 'A single anecdote opens the passage, which then moves to standard layouts surviving the machines. That widening from incident to trend is the structure.', '{"D": "The passage does not settle whether the clerk was right.", "B": "Manufacturing methods are not described.", "C": "No two offices are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-076', 'HDSAT-RW-M13-INFO-076', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'For decades a population of whales was said to migrate along a single corridor. The passage describes a tagging study that recorded several routes, then presents an alternative explanation: the earlier conclusion rested on sightings from ships that all traveled the same lane.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It presents an established claim, reports evidence against it, and offers a reason the claim persisted."}, {"id": "B", "text": "It argues that tagging studies are unreliable."}, {"id": "C", "text": "It compares whale populations in two oceans."}, {"id": "D", "text": "It describes a single tagged whale in detail."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-076', 'A', ARRAY['A']::TEXT[], 'The text states the old claim, gives tag data that complicate it, and explains why ship-based sightings produced it. That three-part movement is the structure.', '{"D": "The tagging study covers several routes, not one whale.", "B": "The passage relies on the tagging study as evidence.", "C": "Only one population is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-077', 'HDSAT-RW-M13-INFO-077', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The passage reports that library visits rose after a branch extended its evening hours. It then cautions that the increase was concentrated among students, and that overall borrowing did not change.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It presents a result and then narrows what that result shows."}, {"id": "B", "text": "It describes a library''s budget in detail."}, {"id": "C", "text": "It argues that libraries should close earlier."}, {"id": "D", "text": "It compares two cities'' library systems."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-077', 'A', ARRAY['A']::TEXT[], 'A rise in visits is reported first, then limited by the detail about students and unchanged borrowing. That is a result followed by a narrowing qualification.', '{"C": "The passage reports an extension, not a recommendation to close earlier.", "D": "Only one branch is discussed.", "B": "Budget figures are not given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-INFO-078', 'HDSAT-RW-M13-INFO-078', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The passage describes engineers who added a slight curve to a footbridge to make it look lighter. It then explains that the curve changed how wind moved across the deck, which reduced a vibration the original design had suffered.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a design choice made for appearance and explains an unintended structural benefit."}, {"id": "B", "text": "It describes a bridge failure in detail."}, {"id": "C", "text": "It compares the costs of two bridges."}, {"id": "D", "text": "It argues that the engineers ignored safety concerns."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-INFO-078', 'A', ARRAY['A']::TEXT[], 'The curve was added for looks, and the passage then credits it with an aerodynamic benefit nobody designed for. That is the structure.', '{"D": "The passage shows the design performing better, not safety being ignored.", "C": "No costs are mentioned.", "B": "A vibration is reduced, not a failure described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-001', 'HDSAT-RW-M13-LANG-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The archive''s catalogue was so ______ that a researcher could locate a single letter by its date, its sender, or the town it was posted from.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "hasty"}, {"id": "B", "text": "sparse"}, {"id": "C", "text": "illegible"}, {"id": "D", "text": "thorough"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-001', 'D', ARRAY['D']::TEXT[], 'The catalogue lets a researcher search by three separate fields, which is only possible if the records are complete and carefully kept. ''Thorough'' names exactly that completeness.', '{"A": "''Hasty'' describes work done too quickly to be reliable, and a hasty catalogue would not support three search fields.", "C": "''Illegible'' is about handwriting that cannot be read, not about how completely a catalogue is organized.", "B": "''Sparse'' means thinly populated, the opposite of a catalogue detailed enough to locate one letter."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-002', 'HDSAT-RW-M13-LANG-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Because the ferry schedule shifts with the tide, the printed timetable is only ______ : passengers are told to check the harbor board before boarding.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "permanent"}, {"id": "B", "text": "provisional"}, {"id": "C", "text": "compulsory"}, {"id": "D", "text": "decorative"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-002', 'B', ARRAY['B']::TEXT[], 'A timetable that changes with the tide cannot be treated as final, which is why passengers must confirm it on the day. ''Provisional'' means temporary and subject to change.', '{"A": "''Permanent'' contradicts the whole point of checking the harbor board before boarding.", "D": "''Decorative'' says the timetable is ornamental, but the sentence treats it as information that may be out of date.", "C": "''Compulsory'' means required, which does not describe a schedule that may change."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-003', 'HDSAT-RW-M13-LANG-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The first attempts to grow the moss in the lab failed, but the team''s ______ record keeping let them trace each failure to a single variable.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "sporadic"}, {"id": "B", "text": "anonymous"}, {"id": "C", "text": "scrupulous"}, {"id": "D", "text": "careless"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-003', 'C', ARRAY['C']::TEXT[], 'Tracing every failure to one variable requires records that are detailed and consistently kept. ''Scrupulous'' means showing careful attention to detail, which is what made the failures useful.', '{"D": "''Careless'' records would blur the variables together rather than isolate them.", "A": "''Sporadic'' means occurring at irregular intervals, and gaps in the records would defeat the comparison.", "B": "''Anonymous'' means lacking a name, which says nothing about how carefully the notes were made."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-004', 'HDSAT-RW-M13-LANG-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'For a decade the two laboratories published results that seemed ______ , until a shared calibration error showed that both had been measuring the same artifact.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "identical"}, {"id": "B", "text": "preliminary"}, {"id": "C", "text": "unremarkable"}, {"id": "D", "text": "contradictory"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-004', 'D', ARRAY['D']::TEXT[], 'The two labs looked like they disagreed until the error explained the gap, so their published results seemed to conflict. ''Contradictory'' captures that apparent clash.', '{"A": "If the results had seemed identical, discovering a measurement error would not have resolved anything.", "C": "''Unremarkable'' means ordinary, but the sentence describes a decade of notable disagreement.", "B": "''Preliminary'' means early or provisional, and the ten-year span rules that out."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-005', 'HDSAT-RW-M13-LANG-005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The mayor''s speech was ______ in tone: it acknowledged the protesters'' concerns while defending every decision the council had made.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "diplomatic"}, {"id": "B", "text": "perfunctory"}, {"id": "C", "text": "elegiac"}, {"id": "D", "text": "belligerent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-005', 'A', ARRAY['A']::TEXT[], 'The sentence describes a balancing act: conceding the protesters'' concerns without retreating from the council''s record. ''Diplomatic'' names that tactful handling of both sides.', '{"D": "''Belligerent'' means aggressively hostile, which a speech that acknowledges concerns is not.", "C": "''Elegiac'' means mournful, a mood the passage never suggests.", "B": "''Perfunctory'' means done without care, but the sentence describes a deliberate balance rather than routine indifference."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-006', 'HDSAT-RW-M13-LANG-006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The novelist''s early work was ______ , borrowing freely from detective fiction, sea shanties and newspaper columns; critics could not place it in a single tradition.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "eclectic"}, {"id": "B", "text": "unfinished"}, {"id": "C", "text": "austere"}, {"id": "D", "text": "conventional"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-006', 'A', ARRAY['A']::TEXT[], 'The work draws on three unrelated sources, and critics cannot assign it to one tradition, which is exactly what ''eclectic'' means: assembled from a wide range of sources.', '{"C": "''Austere'' means severely plain, the opposite of work that borrows from many genres.", "D": "''Conventional'' work fits an established tradition easily, but the critics cannot place this work at all.", "B": "''Unfinished'' concerns completion, not the mixture of sources that puzzles the critics."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-007', 'HDSAT-RW-M13-LANG-007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Far from being ______ , the committee''s objections were substantial enough to delay the project by two years.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "overdue"}, {"id": "B", "text": "trivial"}, {"id": "C", "text": "technical"}, {"id": "D", "text": "vocal"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-007', 'B', ARRAY['B']::TEXT[], 'The phrase ''far from being'' sets up a contrast with objections serious enough to stall a project for two years, so the blank must mean unimportant. ''Trivial'' supplies exactly that contrast.', '{"C": "''Technical'' objections could easily be substantial, so it does not contrast with the two-year delay.", "D": "''Vocal'' describes how loudly the committee objected, not whether the objections mattered.", "A": "''Overdue'' means late, which has nothing to do with the weight of the objections."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-008', 'HDSAT-RW-M13-LANG-008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The species was thought to be ______ to the island, until a single feather found in a mainland collection forced ornithologists to revise its range.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "harmful"}, {"id": "B", "text": "invisible"}, {"id": "C", "text": "endemic"}, {"id": "D", "text": "indifferent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-008', 'C', ARRAY['C']::TEXT[], 'A species known only from one island is endemic there, and a feather from the mainland is precisely what would overturn that claim. ''Endemic'' means native to and restricted to a particular place.', '{"D": "''Indifferent'' describes an attitude and cannot describe a species'' geographic range.", "A": "''Harmful'' to the island would not be disproved by a feather found elsewhere.", "B": "''Invisible'' is contradicted by decades of observation on the island."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-009', 'HDSAT-RW-M13-LANG-009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The report''s recommendations were ______ : each depended on the success of the one before it, so a delay at any stage would stall the whole plan.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "contradictory"}, {"id": "B", "text": "optional"}, {"id": "C", "text": "inexpensive"}, {"id": "D", "text": "interdependent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-009', 'D', ARRAY['D']::TEXT[], 'Each step relies on the one before it, so the recommendations hold one another up. ''Interdependent'' means mutually reliant, which explains why one delay stalls everything.', '{"B": "''Optional'' steps could be skipped without stalling the plan.", "A": "''Contradictory'' recommendations would conflict with one another, not build in sequence.", "C": "''Inexpensive'' concerns cost, and the sentence is about sequencing rather than money."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-010', 'HDSAT-RW-M13-LANG-010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The museum''s new labels are ______ : they give the date, the material and the workshop, but say nothing about what the object meant to its owners.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "cryptic"}, {"id": "B", "text": "lavish"}, {"id": "C", "text": "spare"}, {"id": "D", "text": "outdated"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-010', 'C', ARRAY['C']::TEXT[], 'The labels offer a few hard facts and nothing more, which the colon makes explicit. ''Spare'' means restrained and economical, matching labels limited to date, material and workshop.', '{"B": "''Lavish'' means generous or elaborate, the opposite of three bare facts.", "A": "''Cryptic'' means puzzling, but the problem here is missing interpretation rather than unclear wording.", "D": "''Outdated'' concerns accuracy over time, which the sentence never raises."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-011', 'HDSAT-RW-M13-LANG-011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'His account of the expedition is ______ rather than comprehensive: whole weeks are compressed into a paragraph while a single afternoon occupies thirty pages.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "tedious"}, {"id": "B", "text": "exhaustive"}, {"id": "C", "text": "selective"}, {"id": "D", "text": "impartial"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-011', 'C', ARRAY['C']::TEXT[], 'The account skips over weeks and lingers on one afternoon, so it chooses what to include instead of covering everything. ''Selective'' names that uneven emphasis, which the contrast with ''comprehensive'' reinforces.', '{"B": "''Exhaustive'' means complete, the very quality the phrase ''rather than comprehensive'' denies.", "D": "''Impartial'' concerns fairness, not the proportion of space given to each event.", "A": "''Tedious'' describes how boring the account is, not how it distributes attention."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-012', 'HDSAT-RW-M13-LANG-012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The new evidence did not ______ the theory so much as qualify it: the core mechanism held, but only within a narrower range of temperatures.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "refute"}, {"id": "B", "text": "simplify"}, {"id": "C", "text": "confirm"}, {"id": "D", "text": "publicize"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-012', 'A', ARRAY['A']::TEXT[], 'The phrase ''did not ... so much as qualify'' contrasts a stronger outcome with a milder one. Because the theory survives in a narrower range, the evidence narrows it rather than destroying it, so the blank means disprove.', '{"C": "''Confirm'' is the wrong direction: the sentence says the theory had to be qualified, not supported.", "D": "''Publicize'' means to make widely known, which evidence gathered in a lab does not do to a theory.", "B": "''Simplify'' concerns clarity, not whether the theory survives the new measurements."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-013', 'HDSAT-RW-M13-LANG-013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The town''s response to the drought was ______ : households repaired leaks, schools shortened showers, and the council banned lawn watering within a month.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "temporary"}, {"id": "B", "text": "expensive"}, {"id": "C", "text": "coordinated"}, {"id": "D", "text": "reluctant"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-013', 'C', ARRAY['C']::TEXT[], 'Three separate groups acted at the same time and in the same direction, which is what ''coordinated'' describes. The single month shows how quickly the pieces moved together.', '{"D": "''Reluctant'' would mean households and the council resisted, but they acted within a month.", "B": "The measures listed save water; nothing in the sentence concerns their cost.", "A": "''Temporary'' concerns duration, while the sentence emphasizes how the three responses fit together."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-014', 'HDSAT-RW-M13-LANG-014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The critic''s praise was ______ : she admired the novel''s ambition while doubting that a single reader would finish it.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "unqualified"}, {"id": "B", "text": "effusive"}, {"id": "C", "text": "anonymous"}, {"id": "D", "text": "qualified"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-014', 'D', ARRAY['D']::TEXT[], 'Admiration paired with a serious doubt makes the praise conditional rather than absolute. ''Qualified'' means limited by reservations, which the second half of the sentence spells out.', '{"A": "''Unqualified'' praise would be complete and unreserved, but the critic doubts anyone will finish the book.", "B": "''Effusive'' praise pours out enthusiastically and would not include the doubt.", "C": "''Anonymous'' means unnamed, which has nothing to do with the strength of the praise."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-015', 'HDSAT-RW-M13-LANG-015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The valley''s isolation, once a ______ , became an advantage when remote work allowed residents to keep city salaries while living among the orchards.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "liability"}, {"id": "B", "text": "myth"}, {"id": "C", "text": "privilege"}, {"id": "D", "text": "luxury"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-015', 'A', ARRAY['A']::TEXT[], 'The sentence turns on a reversal: what was once a disadvantage became an advantage. ''Liability'' names a drawback, completing that before-and-after contrast.', '{"D": "''Luxury'' is something desirable, so it could not become an advantage later.", "B": "''Myth'' would mean the isolation was not real, which the orchards and the commute contradict.", "C": "''Privilege'' is already positive, leaving nothing for the word ''became'' to reverse."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-016', 'HDSAT-RW-M13-LANG-016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'The committee treated the complaint as ______ , filing it without reading it, and only later discovered that it described a structural flaw in the bridge.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "fraudulent"}, {"id": "B", "text": "unprecedented"}, {"id": "C", "text": "routine"}, {"id": "D", "text": "urgent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-016', 'C', ARRAY['C']::TEXT[], 'The complaint was filed unread, the way an ordinary piece of paperwork is handled. ''Routine'' explains why nobody examined it closely enough to notice the flaw.', '{"D": "An urgent complaint would have been read immediately rather than filed unread.", "A": "''Fraudulent'' means dishonest, and the passage says the complaint turned out to be accurate.", "B": "''Unprecedented'' means never seen before, which would have drawn attention rather than indifference."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-017', 'HDSAT-RW-M13-LANG-017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Because the two datasets were gathered with different instruments, their agreement on the final figure is more ______ than conclusive.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "suggestive"}, {"id": "B", "text": "decisive"}, {"id": "C", "text": "accidental"}, {"id": "D", "text": "negligible"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-017', 'A', ARRAY['A']::TEXT[], 'Different instruments make a matching result encouraging without proving it, so the agreement hints at a conclusion rather than establishing one. ''Suggestive'' means pointing toward something without settling it.', '{"B": "''Decisive'' would mean the agreement settles the question, which the phrase ''more ... than conclusive'' denies.", "C": "''Accidental'' would dismiss the agreement as coincidence, but the sentence treats it as meaningful evidence.", "D": "''Negligible'' would mean the agreement does not matter, contradicting the attention the sentence gives it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-018', 'HDSAT-RW-M13-LANG-018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The recipe is ______ in its demands: it asks for flour, water and salt, and nothing else.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "extravagant"}, {"id": "B", "text": "delicate"}, {"id": "C", "text": "vague"}, {"id": "D", "text": "minimal"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-018', 'D', ARRAY['D']::TEXT[], 'The colon lists three ordinary ingredients and rules out everything else. ''Minimal'' means the smallest possible in amount, which matches a recipe that asks for nothing more.', '{"A": "''Extravagant'' would mean the recipe demands costly or excessive ingredients.", "C": "''Vague'' would mean the recipe is unclear, but the sentence lists its ingredients exactly.", "B": "''Delicate'' describes something easily damaged, not a short ingredient list."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-019', 'HDSAT-RW-M13-LANG-019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The playwright''s dialogue is ______ ; characters rarely finish a sentence, and the pauses carry as much information as the words.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "fragmentary"}, {"id": "B", "text": "continuous"}, {"id": "C", "text": "formal"}, {"id": "D", "text": "ornate"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-019', 'A', ARRAY['A']::TEXT[], 'Sentences that stop unfinished are broken into pieces, which is what ''fragmentary'' means. The pauses doing part of the work reinforce that the speech is incomplete rather than polished.', '{"D": "''Ornate'' means elaborately decorated, while these lines trail off.", "B": "''Continuous'' contradicts characters who rarely finish a sentence.", "C": "''Formal'' concerns register, and unfinished sentences cut against formality."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-020', 'HDSAT-RW-M13-LANG-020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'The proposal was ______ in scope: it promised to reform hiring, housing and transit in a single budget cycle, and it collapsed under its own ambition.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "incremental"}, {"id": "B", "text": "sweeping"}, {"id": "C", "text": "modest"}, {"id": "D", "text": "ambiguous"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-020', 'B', ARRAY['B']::TEXT[], 'Three major policy areas in one budget cycle is an enormous reach, and the plan fails because of that breadth. ''Sweeping'' means wide-ranging, matching both the list and the collapse.', '{"C": "''Modest'' scope could not plausibly collapse under its own ambition.", "D": "''Ambiguous'' concerns clarity, while the list of three reforms is quite specific.", "A": "''Incremental'' means proceeding in small steps, the opposite of three reforms at once."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-021', 'HDSAT-RW-M13-LANG-021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The village''s oral histories are ______ : no two tellings agree on the name of the first settler, yet each preserves a detail the others have lost.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "brief"}, {"id": "B", "text": "transcribed"}, {"id": "C", "text": "identical"}, {"id": "D", "text": "inconsistent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-021', 'D', ARRAY['D']::TEXT[], 'Tellings that disagree with one another do not match, which is what ''inconsistent'' means. The detail that each version uniquely preserves explains why the differences are still valuable.', '{"C": "''Identical'' directly contradicts the claim that no two tellings agree.", "B": "Whether the stories were written down says nothing about their disagreement.", "A": "''Brief'' concerns length, and the sentence is about how the versions differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-022', 'HDSAT-RW-M13-LANG-022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The instructions were ______ enough that a first-time user could assemble the shelf without calling the helpline.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "lengthy"}, {"id": "B", "text": "vague"}, {"id": "C", "text": "implicit"}, {"id": "D", "text": "explicit"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-022', 'D', ARRAY['D']::TEXT[], 'A beginner succeeding without help requires directions that state each step plainly. ''Explicit'' means fully and clearly expressed, leaving nothing to be inferred.', '{"C": "''Implicit'' means suggested rather than stated, which would leave a beginner guessing.", "B": "''Vague'' instructions would send the user to the helpline.", "A": "''Lengthy'' means long, and long instructions are not necessarily clear."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-023', 'HDSAT-RW-M13-LANG-023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The senator''s remarks were deliberately ______ , offering neither support nor opposition to the bill and leaving reporters to guess.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "inflammatory"}, {"id": "B", "text": "noncommittal"}, {"id": "C", "text": "decisive"}, {"id": "D", "text": "concise"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-023', 'B', ARRAY['B']::TEXT[], 'Refusing to take either side is the definition of a noncommittal statement, which is why reporters are left guessing. The word ''deliberately'' signals that the ambiguity was a choice.', '{"C": "''Decisive'' remarks would settle the question instead of leaving it open.", "A": "''Inflammatory'' remarks would provoke a reaction, but these remarks avoid one.", "D": "''Concise'' means brief, and a short statement can still take a clear position."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-024', 'HDSAT-RW-M13-LANG-024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'The field''s early findings were ______ by later work, but they were not worthless: they mapped the questions that are still being asked.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "duplicated"}, {"id": "B", "text": "superseded"}, {"id": "C", "text": "ignored"}, {"id": "D", "text": "financed"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-024', 'B', ARRAY['B']::TEXT[], 'Later work replaced the earlier conclusions while still depending on the questions they identified. ''Superseded'' means replaced by something newer, which fits the contrast with ''not worthless''.', '{"A": "''Duplicated'' would mean later work repeated the findings rather than replacing them.", "C": "Ignored work would not explain why its questions are still being asked.", "D": "Financed findings are funded, not replaced, and the sentence is about intellectual succession."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-025', 'HDSAT-RW-M13-LANG-025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The shelter''s policy is ______ : animals are held for seven days, then placed, and never euthanized for lack of space.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "generous"}, {"id": "B", "text": "unambiguous"}, {"id": "C", "text": "temporary"}, {"id": "D", "text": "contested"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-025', 'B', ARRAY['B']::TEXT[], 'The colon states the rule in three exact steps with no room for interpretation. ''Unambiguous'' means admitting only one meaning, which is what the fixed seven-day period and the stated outcome provide.', '{"A": "''Generous'' judges the policy''s kindness, not the precision that the numbered steps illustrate.", "C": "''Temporary'' means short-lived, but the sentence describes a standing rule.", "D": "''Contested'' means disputed, and nothing in the sentence suggests disagreement."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-026', 'HDSAT-RW-M13-LANG-026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The garden''s harvest was ______ : a dry spring, a late frost and an early heat wave left almost nothing to pick.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "delayed"}, {"id": "B", "text": "predictable"}, {"id": "C", "text": "abundant"}, {"id": "D", "text": "meager"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-026', 'D', ARRAY['D']::TEXT[], 'Three separate weather shocks left almost nothing to pick, so the harvest was small. ''Meager'' means lacking in quantity, which the colon makes explicit.', '{"C": "''Abundant'' is the opposite of a garden with almost nothing to pick.", "B": "''Predictable'' concerns expectation, and the string of shocks suggests the opposite.", "A": "''Delayed'' means late, but the obstacles destroyed the crop rather than postponing it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-027', 'HDSAT-RW-M13-LANG-027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The company''s growth was ______ : revenue doubled in the spring, fell by a third in the summer, and doubled again in the autumn.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "seasonal"}, {"id": "B", "text": "erratic"}, {"id": "C", "text": "steady"}, {"id": "D", "text": "modest"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-027', 'B', ARRAY['B']::TEXT[], 'Revenue swings sharply up and down without a settled direction, which is what ''erratic'' describes. The repeated reversals make the pattern irregular rather than predictable.', '{"C": "''Steady'' growth would not fall by a third midway through the year.", "D": "''Modest'' growth would not double twice in a single year.", "A": "''Seasonal'' would predict a repeating annual cycle, but the pattern here is doubling followed by a sharp fall."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-028', 'HDSAT-RW-M13-LANG-028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Her argument is ______ in the best sense: it states the strongest version of the opposing case before dismantling it.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "sentimental"}, {"id": "B", "text": "hasty"}, {"id": "C", "text": "dogmatic"}, {"id": "D", "text": "rigorous"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-028', 'D', ARRAY['D']::TEXT[], 'Meeting the strongest opposing case before answering it is demanding, careful reasoning, which is what ''rigorous'' means. The qualifier ''in the best sense'' signals that the word is praise.', '{"C": "''Dogmatic'' means asserting without evidence, which is the opposite of engaging the opposing case.", "A": "''Sentimental'' appeals to emotion, and the sentence describes an argument about reasoning.", "B": "''Hasty'' means rushed, while addressing the strongest counterargument takes care."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-029', 'HDSAT-RW-M13-LANG-029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The bridge''s design was ______ for its time, using a method that engineers did not adopt widely until thirty years later.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "temporary"}, {"id": "B", "text": "innovative"}, {"id": "C", "text": "costly"}, {"id": "D", "text": "conventional"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-029', 'B', ARRAY['B']::TEXT[], 'Using a method three decades before engineers adopted it means the design introduced something new. ''Innovative'' names that originality relative to its period.', '{"D": "''Conventional'' would mean the method was already standard, but adoption came thirty years later.", "C": "''Costly'' concerns expense, and the sentence emphasizes timing rather than price.", "A": "''Temporary'' describes how long the bridge lasted, not how early the method appeared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-030', 'HDSAT-RW-M13-LANG-030', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'The editor''s notes were ______ , correcting errors of fact while leaving the writer''s odd, unfinished sentences exactly as they stood.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "exhaustive"}, {"id": "B", "text": "judicious"}, {"id": "C", "text": "hostile"}, {"id": "D", "text": "indiscriminate"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-030', 'B', ARRAY['B']::TEXT[], 'The editor distinguishes between what must change and what should be left alone, which is a matter of good judgment. ''Judicious'' means showing sound judgment, matching that selective correction.', '{"D": "''Indiscriminate'' editing would rewrite the odd sentences too, not preserve them.", "C": "''Hostile'' notes would attack the writer''s style rather than protect it.", "A": "''Exhaustive'' notes would touch everything, but the editor deliberately leaves the sentences alone."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-031', 'HDSAT-RW-M13-LANG-031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'When the river rose above the footbridge ______ the crew closed the lower trail.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": ", "}, {"id": "C", "text": "; "}, {"id": "D", "text": " - "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-031', 'B', ARRAY['B']::TEXT[], 'The opening word ''When'' makes the first part a dependent clause, which must be separated from the main clause by a comma. A comma after ''footbridge'' marks that boundary.', '{"D": "A hyphen is not a clause boundary, so the dependent clause runs straight into the main clause.", "C": "A semicolon must join two independent clauses, and the opening part cannot stand alone.", "A": "A colon must follow an independent clause, which ''When the river rose above the footbridge'' is not."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-032', 'HDSAT-RW-M13-LANG-032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The archive holds three collections ______ letters, ledgers and maps.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " - "}, {"id": "B", "text": "; "}, {"id": "C", "text": ", "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-032', 'D', ARRAY['D']::TEXT[], 'A complete clause comes before the blank and a list follows it, which is the standard use of a colon. The colon signals that the three items define the collections just mentioned.', '{"B": "A semicolon needs an independent clause after it, and a bare list is not one.", "C": "A comma would attach the list too loosely and leave the items without an introducer.", "A": "A hyphen leaves ''three collections letters'' reading as a single confused noun phrase."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-033', 'HDSAT-RW-M13-LANG-033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In the spring of 1998 ______ a volunteer group began mapping the marsh.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": " - "}, {"id": "C", "text": "; "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-033', 'D', ARRAY['D']::TEXT[], 'A long introductory phrase is set off from the main clause by a comma, which is what ''In the spring of 1998'' requires here.', '{"B": "Without a comma the phrase is read as part of the subject.", "C": "A semicolon would need a full clause on each side, and the phrase before the blank has no verb.", "A": "A colon must be preceded by an independent clause, not a time phrase."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-034', 'HDSAT-RW-M13-LANG-034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The bakery opens at five ______ the line often reaches the corner by seven.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": ", and "}, {"id": "C", "text": " - "}, {"id": "D", "text": "; and "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-034', 'B', ARRAY['B']::TEXT[], 'Two independent clauses joined by the coordinating conjunction ''and'' need a comma before the conjunction. There the comma and the conjunction appear together.', '{"A": "A comma alone between two independent clauses creates a comma splice.", "C": "A hyphen is not a clause boundary, so the two clauses form a run-on sentence.", "D": "A semicolon and ''and'' together are redundant; a semicolon already joins the clauses."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-035', 'HDSAT-RW-M13-LANG-035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The team''s lead engineer, a specialist in soil movement ______ warned that the slope was unstable.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": ": "}, {"id": "C", "text": "; "}, {"id": "D", "text": " - "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-035', 'A', ARRAY['A']::TEXT[], 'The phrase ''a specialist in soil movement'' is an appositive inserted into the sentence, so it needs a comma both before and after. The comma after the blank closes it.', '{"D": "Leaving the appositive unclosed makes the sentence hard to parse.", "C": "A semicolon cannot close an appositive, and no independent clause follows it.", "B": "A colon would falsely announce a list or explanation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-036', 'HDSAT-RW-M13-LANG-036', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The ranger carried three things ______ a map, a compass and a full water bottle.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": " - "}, {"id": "C", "text": "; "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-036', 'D', ARRAY['D']::TEXT[], 'An independent clause introduces a list of the three things, and a colon is the mark that announces such a list.', '{"C": "A semicolon requires an independent clause after it, but a list is not a clause.", "A": "A comma leaves the list attached without a clear introducer.", "B": "A hyphen joins the clause to its list without introducing it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-037', 'HDSAT-RW-M13-LANG-037', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In fact ______ the earliest surviving map omits the river entirely.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": " - "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-037', 'A', ARRAY['A']::TEXT[], '''In fact'' is an introductory transition, and an introductory element is followed by a comma before the main clause begins.', '{"C": "A hyphen after the transition fuses it with the subject of the sentence.", "B": "A semicolon needs a complete clause before it, and ''In fact'' is only a transition.", "D": "A colon cannot follow a two-word transition that has no clause of its own."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-038', 'HDSAT-RW-M13-LANG-038', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The trail was muddy ______ the group turned back before noon.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": " - "}, {"id": "C", "text": ". "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-038', 'D', ARRAY['D']::TEXT[], 'Both halves are independent clauses that closely relate, so a semicolon correctly separates them.', '{"A": "A comma alone between two independent clauses is a comma splice.", "B": "A hyphen is not a clause boundary, so the two clauses run together.", "C": "A period would start a new sentence, but the following word ''the'' is not capitalized."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-039', 'HDSAT-RW-M13-LANG-039', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The first train left at dawn ______ the second did not arrive until noon.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": ": "}, {"id": "D", "text": " - "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-039', 'B', ARRAY['B']::TEXT[], 'Two independent clauses that are closely related and joined without a conjunction take a semicolon.', '{"A": "A comma between two independent clauses is a splice.", "D": "A hyphen does not join two clauses and leaves a run-on sentence.", "C": "A colon would imply that the second clause explains the first, which it does not."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-040', 'HDSAT-RW-M13-LANG-040', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The committee reached one conclusion ______ the plan needed another year of testing.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": ": "}, {"id": "C", "text": " - "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-040', 'B', ARRAY['B']::TEXT[], 'The second half states what the conclusion was, so a colon introduces it as an explanation of the first clause.', '{"D": "A semicolon would present the two clauses as equal rather than as conclusion and content.", "A": "A comma alone between two independent clauses is a splice.", "C": "A hyphen leaves the two clauses running together."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-041', 'HDSAT-RW-M13-LANG-041', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The novelist, who had lived in the city for thirty years ______ refused to set a single scene there.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": ", "}, {"id": "C", "text": " - "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-041', 'B', ARRAY['B']::TEXT[], 'The clause beginning with ''who'' is non-essential information about the novelist, so it must be closed with a comma before the main verb ''refused''.', '{"C": "A hyphen does not close the relative clause, so it blurs into the main clause.", "A": "A semicolon cannot close a relative clause.", "D": "A colon would incorrectly announce an explanation or list."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-042', 'HDSAT-RW-M13-LANG-042', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The bridge was sound ______ its railings did not meet the current code.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", however, "}, {"id": "B", "text": " however "}, {"id": "C", "text": ", however "}, {"id": "D", "text": "; however, "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-042', 'D', ARRAY['D']::TEXT[], 'Two independent clauses are joined by the transition ''however'', which needs a semicolon before it and a comma after it.', '{"A": "A comma before ''however'' creates a splice between the two clauses.", "B": "The transition is left without either boundary, producing a run-on.", "C": "The comma after the blank is missing, so the transition runs into its own clause."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
