INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-043', 'D', ARRAY['D']::TEXT[], 'The contrast between brevity and full coverage is carried by a conjunctive adverb, which requires a semicolon before it and a comma after it when it joins two independent clauses.', '{"B": "A comma before ''nevertheless'' leaves two independent clauses spliced together.", "C": "With no punctuation around it, the transition merges both clauses into a run-on.", "A": "The comma after ''nevertheless'' is missing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
