INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-044', 'C', ARRAY['C']::TEXT[], 'The ''which'' clause adds non-essential detail about an already identified plot, so it is set off by a comma.', '{"D": "A hyphen is not the mark for a non-essential clause, which the definite ''the shaded plot'' does not need.", "B": "A semicolon must join independent clauses, and a ''which'' clause is dependent.", "A": "A colon would introduce an explanation of the whole clause rather than a modifier."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
