INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-045', 'A', ARRAY['A']::TEXT[], 'Both parts are full clauses joined without a conjunction, so a semicolon is the correct boundary.', '{"D": "A comma alone would splice the clauses.", "B": "A hyphen does not separate clauses and creates a run-on.", "C": "A colon would wrongly present the crowd as an explanation of the scheduled time."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
