INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-046', 'C', ARRAY['C']::TEXT[], 'The prepositional phrase ''Before the invention of the telegraph'' introduces the main clause and is followed by a comma.', '{"A": "A hyphen leaves the phrase attached too tightly to ''news''.", "D": "A semicolon needs an independent clause before it, and the phrase has none.", "B": "A colon must follow a complete clause."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
