INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-047', 'C', ARRAY['C']::TEXT[], 'The two independent clauses are related by contrast, and a conjunctive adverb joining them takes a semicolon before and a comma after.', '{"A": "A comma before ''however'' splices the clauses.", "B": "Without punctuation the transition fuses the clauses.", "D": "The comma that must follow ''however'' is missing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
