INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-051', 'B', ARRAY['B']::TEXT[], 'The relative clause ''which the board had rejected twice'' interrupts the sentence and must be closed with a comma before the verb ''was revived''.', '{"D": "A hyphen does not close the relative clause, so the subject and verb are hard to identify.", "A": "A semicolon cannot close a relative clause.", "C": "A colon would falsely introduce an explanation after a dependent clause."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-052', 'HDSAT-RW-M13-LANG-052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'Mara packed the samples carefully ______ she knew the return trip would take three days.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " - "}, {"id": "B", "text": "; "}, {"id": "C", "text": ", "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-052', 'B', ARRAY['B']::TEXT[], 'The second half is an independent clause, so it is separated from the first by a semicolon.', '{"C": "A comma alone would splice two independent clauses.", "A": "A hyphen leaves the sentence running on.", "D": "A colon would imply that the trip explains the packing, yet the sentence gives the trip as a separate fact."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-053', 'HDSAT-RW-M13-LANG-053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'The council approved the budget ______ the mayor had threatened a veto.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": ", "}, {"id": "C", "text": "; "}, {"id": "D", "text": " - "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-053', 'C', ARRAY['C']::TEXT[], 'Both halves can stand alone as sentences, and they are joined without a conjunction, so a semicolon marks the boundary.', '{"B": "A comma would splice the two independent clauses.", "D": "A hyphen is not a clause boundary, and the clauses merge into a run-on.", "A": "A colon would present the veto as an explanation of the approval, which reverses their relation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-054', 'HDSAT-RW-M13-LANG-054', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'The letters were stored in a damp cellar for decades ______ many of them are still legible.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " surprisingly "}, {"id": "B", "text": ", surprisingly, "}, {"id": "C", "text": "; surprisingly, "}, {"id": "D", "text": ", surprisingly "}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-054', 'C', ARRAY['C']::TEXT[], 'The contrast between decades in a damp cellar and still-legible letters is carried by a conjunctive adverb, which takes a semicolon before it and a comma after it.', '{"B": "A comma before the adverb leaves the two clauses spliced.", "A": "Without punctuation the transition merges the clauses into a run-on.", "D": "The comma after the adverb is missing, so the boundary is incomplete."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-055', 'HDSAT-RW-M13-LANG-055', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The first trials used a copper mesh. ______ , the second series used a cheaper alloy that corroded within weeks.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Likewise"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "By contrast"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-055', 'C', ARRAY['C']::TEXT[], 'The second series changes the material and suffers a different outcome, so the two trials are being set against each other. ''By contrast'' marks that difference.', '{"B": "''Therefore'' would claim the second series is a consequence of the first.", "D": "''For example'' would present the second series as an illustration of the first.", "A": "''Likewise'' would claim the trials were similar, but the alloy is cheaper and corroded."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-056', 'HDSAT-RW-M13-LANG-056', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The river carried less silt after the dam was built. ______ , the downstream wetlands began to shrink.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "As a result"}, {"id": "B", "text": "Similarly"}, {"id": "C", "text": "Nevertheless"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-056', 'A', ARRAY['A']::TEXT[], 'Less silt reaching the wetlands is the cause, and their shrinking is the effect. ''As a result'' signals that causal link.', '{"C": "''Nevertheless'' would set the shrinking against the silt loss as a contrast.", "D": "''For instance'' would treat the shrinking as one example of silt loss.", "B": "''Similarly'' would make the two statements parallel rather than cause and effect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-057', 'HDSAT-RW-M13-LANG-057', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Most of the letters are routine requests for receipts. ______ , one of them describes a fire that destroyed half the town.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Finally"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "Thus"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-057', 'D', ARRAY['D']::TEXT[], 'A remarkable letter stands out against a run of ordinary ones, which is a contrast rather than an addition. ''However'' marks that shift.', '{"C": "''Thus'' would make the fire letter a result of the routine requests.", "B": "''In addition'' treats the letter as one more routine item, which the description contradicts.", "A": "''Finally'' suggests the end of a sequence, not an exception to it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-058', 'HDSAT-RW-M13-LANG-058', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The adhesive holds at room temperature. ______ , it fails completely below freezing.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Even so"}, {"id": "B", "text": "Moreover"}, {"id": "C", "text": "In short"}, {"id": "D", "text": "Consequently"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-058', 'A', ARRAY['A']::TEXT[], 'The second sentence limits the first: the adhesive works indoors but not in cold. ''Even so'' introduces that qualification.', '{"D": "''Consequently'' would make the failure a result of holding at room temperature.", "B": "''Moreover'' would add a second strength rather than a weakness.", "C": "''In short'' would summarize, but the second sentence introduces new information."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-059', 'HDSAT-RW-M13-LANG-059', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The survey found that students who slept seven hours scored higher. ______ , the authors caution that the sample was small.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Consequently"}, {"id": "B", "text": "For example"}, {"id": "C", "text": "Still"}, {"id": "D", "text": "Moreover"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-059', 'C', ARRAY['C']::TEXT[], 'The caution does not cancel the finding; it sits alongside it as a limitation. ''Still'' signals that the result stands despite the caveat.', '{"A": "''Consequently'' would make the caution a result of the survey.", "D": "''Moreover'' would add further support rather than a limitation.", "B": "''For example'' would offer the caution as an instance of the finding."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-060', 'HDSAT-RW-M13-LANG-060', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Fossils of the fern appear in every layer of the deposit. ______ , the plant must have grown there for millions of years.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Instead"}, {"id": "B", "text": "Nevertheless"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "Meanwhile"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-060', 'C', ARRAY['C']::TEXT[], 'The continuous fossil record is the evidence, and the long presence of the plant is the conclusion drawn from it. ''Therefore'' marks that inference.', '{"A": "''Instead'' would replace the evidence with a different claim.", "D": "''Meanwhile'' would place the conclusion in a separate time frame.", "B": "''Nevertheless'' would present the conclusion as a concession."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-061', 'HDSAT-RW-M13-LANG-061', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The city planted shade trees along the avenue. ______ , summer surface temperatures on the street fell by several degrees.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "As a result"}, {"id": "B", "text": "For instance"}, {"id": "C", "text": "Admittedly"}, {"id": "D", "text": "In contrast"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-061', 'A', ARRAY['A']::TEXT[], 'Planting trees produced the cooler street, so the second sentence reports the effect of the first. ''As a result'' supplies that causal link.', '{"D": "''In contrast'' would set the cooling against the planting.", "B": "''For instance'' would treat the cooling as one example of planting trees.", "C": "''Admittedly'' would introduce a concession, not an outcome."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-062', 'HDSAT-RW-M13-LANG-062', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The manuscript was copied by three different scribes. ______ , each scribe used a different shade of ink.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "Rather"}, {"id": "C", "text": "Moreover"}, {"id": "D", "text": "Thus"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-062', 'C', ARRAY['C']::TEXT[], 'The second sentence adds another piece of evidence that the manuscript had several hands. ''Moreover'' signals that additional support.', '{"A": "''However'' would set the ink detail against the scribes, but the two facts agree.", "D": "''Thus'' would make the ink shades a consequence of having three scribes.", "B": "''Rather'' would replace the first claim instead of adding to it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-063', 'HDSAT-RW-M13-LANG-063', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The policy reduced paperwork for small clinics. ______ , it increased the reporting burden on hospitals.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "Similarly"}, {"id": "C", "text": "On the other hand"}, {"id": "D", "text": "In short"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-063', 'C', ARRAY['C']::TEXT[], 'One group benefits while another takes on more work, so the second sentence balances the first. ''On the other hand'' marks that trade-off.', '{"B": "''Similarly'' would claim hospitals also saw less paperwork.", "A": "''Therefore'' would make the hospital burden a result of helping clinics.", "D": "''In short'' would summarize rather than introduce the other side."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-064', 'HDSAT-RW-M13-LANG-064', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The instrument is light enough for one researcher to carry. ______ , it still requires a stable tripod to record accurately.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Nevertheless"}, {"id": "B", "text": "Consequently"}, {"id": "C", "text": "Likewise"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-064', 'A', ARRAY['A']::TEXT[], 'Portability is an advantage, but the tripod requirement limits it, so the second sentence qualifies the first. ''Nevertheless'' marks that contrast.', '{"B": "''Consequently'' would make the tripod a result of the instrument being light.", "C": "''Likewise'' would add a second advantage rather than a limitation.", "D": "''For example'' would offer the tripod as an instance of portability."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-065', 'HDSAT-RW-M13-LANG-065', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Some mosses survive years of drought in a dormant state. ______ , they can revive within hours of the first rain.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Instead"}, {"id": "B", "text": "Indeed"}, {"id": "C", "text": "Meanwhile"}, {"id": "D", "text": "Otherwise"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-065', 'B', ARRAY['B']::TEXT[], 'The rapid revival strengthens the claim about surviving drought, so the second sentence intensifies the first. ''Indeed'' marks that reinforcement.', '{"D": "''Otherwise'' would present the revival as an alternative to surviving.", "A": "''Instead'' would replace the dormancy with the revival.", "C": "''Meanwhile'' would place the two facts in separate time frames."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-066', 'HDSAT-RW-M13-LANG-066', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The earliest surviving map omits the northern islands entirely. ______ , a later map shows them in careful detail.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "Similarly"}, {"id": "C", "text": "In contrast"}, {"id": "D", "text": "Additionally"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-066', 'C', ARRAY['C']::TEXT[], 'The two maps treat the same islands in opposite ways, so the second sentence contrasts with the first. ''In contrast'' marks that difference.', '{"A": "''Therefore'' would make the detailed map a consequence of the omission.", "D": "''Additionally'' would add a compatible fact rather than a reversal.", "B": "''Similarly'' would claim both maps omit the islands."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-067', 'HDSAT-RW-M13-LANG-067', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The new strain produces more grain per acre. ______ , it matures two weeks earlier, which suits short growing seasons.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Instead"}, {"id": "B", "text": "Nevertheless"}, {"id": "C", "text": "Thus"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-067', 'D', ARRAY['D']::TEXT[], 'Earlier maturity is a second advantage, added to the higher yield. ''In addition'' signals that accumulation of benefits.', '{"A": "''Instead'' would replace the yield advantage with maturity.", "B": "''Nevertheless'' would set the second advantage against the first.", "C": "''Thus'' would make the earlier maturity a result of higher yield."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-068', 'HDSAT-RW-M13-LANG-068', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Museum attendance fell sharply in 2020. ______ , many institutions used the closure to digitize their collections.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Consequently"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Meanwhile"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-068', 'D', ARRAY['D']::TEXT[], 'The two developments happened in the same period without one causing the other, which is what ''Meanwhile'' signals.', '{"A": "''Consequently'' would claim the digitizing caused the attendance drop.", "C": "''For example'' would present digitizing as an instance of low attendance.", "B": "''Therefore'' would make digitizing an effect of the attendance figure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-069', 'HDSAT-RW-M13-LANG-069', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The cake made with butter has a light, open crumb. ______ , the version made with olive oil is noticeably denser.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "In conclusion"}, {"id": "B", "text": "Likewise"}, {"id": "C", "text": "For this reason"}, {"id": "D", "text": "By comparison"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-069', 'D', ARRAY['D']::TEXT[], 'The two versions are being measured against each other on the same quality, texture. ''By comparison'' introduces that direct evaluation.', '{"A": "''In conclusion'' would signal the end of an argument rather than a comparison.", "C": "''For this reason'' would make density a consequence of the butter version.", "B": "''Likewise'' would claim both cakes have the same texture."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-070', 'HDSAT-RW-M13-LANG-070', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'The letters were stored in a damp cellar for decades. ______ , many of them are still legible.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For instance"}, {"id": "B", "text": "Similarly"}, {"id": "C", "text": "Accordingly"}, {"id": "D", "text": "Remarkably"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-070', 'D', ARRAY['D']::TEXT[], 'Long storage in a damp cellar should have ruined the paper, so the survival of the writing is surprising. ''Remarkably'' marks that unexpected outcome.', '{"C": "''Accordingly'' would make legibility a predictable result of damp storage.", "B": "''Similarly'' would compare the storage to the legibility instead of contrasting them.", "A": "''For instance'' would offer legibility as an example of damp storage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-071', 'HDSAT-RW-M13-LANG-071', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'The software flagged one anomaly in ten thousand records. ______ , the flagged records were exactly the ones the auditors had already questioned.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Otherwise"}, {"id": "B", "text": "Notably"}, {"id": "C", "text": "In general"}, {"id": "D", "text": "Instead"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-071', 'B', ARRAY['B']::TEXT[], 'The overlap between the software''s single flag and the auditors'' own suspects is a striking detail worth singling out. ''Notably'' introduces it that way.', '{"A": "''Otherwise'' would present the overlap as an alternative to the flagging.", "C": "''In general'' would generalize from one case rather than emphasize it.", "D": "''Instead'' would replace the flagging with the auditors'' list."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-072', 'HDSAT-RW-M13-LANG-072', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The bridge was designed for a hundred-year lifespan. ______ , the salt used on winter roads has shortened it to sixty.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Similarly"}, {"id": "B", "text": "In practice"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Therefore"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-072', 'B', ARRAY['B']::TEXT[], 'The design intention and the actual outcome differ, so the second sentence reports what happened rather than what was planned. ''In practice'' marks that gap.', '{"C": "''For example'' would present the shortened lifespan as an instance of the design.", "D": "''Therefore'' would make the salt damage a consequence of the design target.", "A": "''Similarly'' would claim the outcome matched the plan."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-073', 'HDSAT-RW-M13-LANG-073', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Easy', 'multiple_choice', 'While researching a seed-lending program at a neighborhood library, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-073', 'B', ARRAY['B']::TEXT[], 'Pairing the program''s scale with its annual cost is the comparison that makes the expense look small. That directly serves the goal of emphasizing low cost.', '{"D": "This sentence traces the program''s growth, which speaks to popularity rather than cost.", "C": "This sentence explains how borrowing works, not what the program costs.", "A": "This sentence recommends expansion, a proposal the notes do not support."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-074', 'HDSAT-RW-M13-LANG-074', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a city''s protected bike lanes, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-074', 'B', ARRAY['B']::TEXT[], 'The goal concerns businesses, so the sentence reporting the sales change that followed the lanes is the one that serves it. The other details describe safety, construction or driver objections.', '{"D": "This reports how much was built, which says nothing about shops.", "A": "This reports a safety outcome rather than an economic one.", "C": "This reports a complaint, not an effect on business."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-075', 'HDSAT-RW-M13-LANG-075', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a restoration of a tidal marsh, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-075', 'A', ARRAY['A']::TEXT[], 'The sentence reporting what changed after the channels reopened is exactly the outcome the goal asks for.', '{"B": "This supplies historical background rather than a result.", "D": "This describes funding, not an ecological outcome.", "C": "This generalizes about marshes elsewhere and mentions no result of this project."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-076', 'HDSAT-RW-M13-LANG-076', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching the history of a public staircase, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-076', 'D', ARRAY['D']::TEXT[], 'Naming both the threat and the residents'' response is what tells the survival story the goal requires.', '{"B": "This gives dimensions and a construction date, not a threat or a rescue.", "A": "This describes upkeep, not how the staircase escaped removal.", "C": "This is a general claim about other cities."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-077', 'HDSAT-RW-M13-LANG-077', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Hard', 'multiple_choice', 'While researching a study of night-shift nurses, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-077', 'A', ARRAY['A']::TEXT[], 'Giving both sleep averages supplies the comparison the study is built on, and closing with the single-hospital caveat supplies its limitation.', '{"B": "This omits the numbers and substitutes a vague claim that sleep matters.", "C": "This reports one group only, so no comparison is made, and adds outside information.", "D": "This discusses nurse preferences, which the notes never mention."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-078', 'HDSAT-RW-M13-LANG-078', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a museum''s handling of a fragile textile, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-078', 'C', ARRAY['C']::TEXT[], 'Linking the damage conservators found to the new rotation schedule explains the change in practice.', '{"D": "This identifies the object but gives no reason for the new policy.", "B": "This reports that an examination happened without connecting it to the change.", "A": "This describes other museums and does not explain this museum''s decision."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-079', 'HDSAT-RW-M13-LANG-079', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a community orchestra, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-079', 'D', ARRAY['D']::TEXT[], 'Setting the founding size beside the current size is precisely a before-and-after comparison.', '{"B": "This describes the concert schedule, not growth over time.", "A": "This explains the funding model rather than change.", "C": "This is a regional claim that says nothing about this orchestra''s history."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-080', 'HDSAT-RW-M13-LANG-080', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Hard', 'multiple_choice', 'While researching a wildfire recovery project, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-080', 'B', ARRAY['B']::TEXT[], 'Pairing the survival difference with the decision it prompted explains the change in approach.', '{"C": "This gives the scale of the fire and the replanting but not the reason for a new method.", "A": "This is a general statement about reforestation timelines.", "D": "This restates the planted acreage without explaining the adjustment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-081', 'HDSAT-RW-M13-LANG-081', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching an urban heat study, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-081', 'D', ARRAY['D']::TEXT[], 'The central finding is the measured relationship between tree density and temperature, which the sentence states with the study''s own numbers.', '{"B": "This describes the method rather than the result.", "C": "This reports variation in cover but not its effect on heat.", "A": "This is a recommendation that follows from the finding, not the finding itself."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M13-LANG-082', 'HDSAT-RW-M13-LANG-082', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Hard', 'multiple_choice', 'While researching a translation of a nineteenth-century novel, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M13-LANG-082', 'B', ARRAY['B']::TEXT[], 'Naming the specific changes in the old translation and the opposite choices in the new one is the comparison the goal asks for.', '{"C": "This reports a disagreement about quality, not what differs between the texts.", "D": "This gives a publication date without describing either translation.", "A": "This is a general remark about translation with no reference to these editions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M13-GEO-H001', 'HDSAT-M13-GEO-H001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Right triangles and trigonometry', 'Medium', 'multiple_choice', 'A landscape designer is laying out a triangular garden bed for a community garden. The two legs measure 3 and 4 centimeters, as shown.', 'What is the length of the hypotenuse?', '[{"id": "A", "text": "7"}, {"id": "B", "text": "5"}, {"id": "C", "text": "6"}, {"id": "D", "text": "1"}]'::jsonb, '{"type": "geometry_figure", "shape": "right_triangle", "caption": "Note: Figure not drawn to scale.", "labels": {"a": "3", "b": "4"}}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-GEO-H001', 'B', ARRAY['B']::TEXT[], 'The legs are perpendicular, so the Pythagorean theorem gives 3^2 + 4^2 = 25, and the square root of 25 is 5 centimeters.', '{"A": "Adding the legs treats the triangle as though the two given sides formed one straight side.", "D": "Subtracting assumes the hypotenuse is the longer leg minus the shorter, which no right triangle allows.", "C": "This is off by two; squaring and adding 3 and 4 gives 25, not 7 squared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
