INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-GEO-H002', 'C', ARRAY['C']::TEXT[], 'The legs are perpendicular, so the Pythagorean theorem gives 5^2 + 12^2 = 169, and the square root of 169 is 13 inches.', '{"B": "Adding the legs treats the triangle as though the two given sides formed one straight side.", "D": "Subtracting assumes the hypotenuse is the longer leg minus the shorter, which no right triangle allows.", "A": "This is off by two; squaring and adding 5 and 12 gives 169, not 15 squared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
