INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-GEO-H003', 'C', ARRAY['C']::TEXT[], 'The legs are perpendicular, so the Pythagorean theorem gives 8^2 + 15^2 = 289, and the square root of 289 is 17 meters.', '{"A": "Adding the legs treats the triangle as though the two given sides formed one straight side.", "B": "Subtracting assumes the hypotenuse is the longer leg minus the shorter, which no right triangle allows.", "D": "This is off by two; squaring and adding 8 and 15 gives 289, not 19 squared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
