INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-GEO-R000', 'A', ARRAY['A']::TEXT[], 'Dividing both sides of \pi r^2 = 36\pi by \pi leaves r^2 = 36, and the square root of 36 is 6.', '{"C": "Halving the area does not give the radius; the radius is the square root of the area divided by \\pi.", "D": "This is three units too large; the square root of the coefficient is exact.", "B": "Dividing by 4 ignores that area grows with the square of the radius."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
