INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-COORD-S000', 'B', ARRAY['B']::TEXT[], 'The line rises 2 units for every 1 unit to the right, so its slope is 2.', '{"C": "This is the y-intercept, the height where the line crosses the y-axis, not its steepness.", "A": "This flips the sign; the line rises (or falls) in the direction shown, giving 2.", "D": "This adds two to the rise; counting the grid shows 2."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
