INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M13-COORD-I000', 'HDSAT-M13-COORD-I000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Algebra', 'Linear functions: slope and intercepts', 'Medium', 'multiple_choice', 'A quilting instructor is checking a joint in a pennant for a library atrium. Line l passes through the points shown on the graph, where each grid square is 1 unit.', 'What is the y-intercept of line l?', '[{"id": "A", "text": "3"}, {"id": "B", "text": "-1"}, {"id": "C", "text": "1"}, {"id": "D", "text": "2"}]'::jsonb, '{"type": "coordinate_plane", "x_min": -6, "x_max": 6, "y_min": -6, "y_max": 6, "x_label": "x", "y_label": "y", "lines": [{"slope": 2, "intercept": 1, "label": "l"}], "points": [{"x": 0, "y": 1}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-COORD-I000', 'C', ARRAY['C']::TEXT[], 'Following the line to the vertical axis gives y = 1 at x = 0, so the y-intercept is 1.', '{"D": "This is the slope: the change in y for each step right, not the crossing height.", "B": "This has the wrong sign; the line crosses at y = 1.", "A": "This is two units too high; the crossing sits on the gridline at 1."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
