INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M13-COORD-Q000', 'HDSAT-M13-COORD-Q000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Advanced Math', 'Quadratic functions: vertex and symmetry', 'Hard', 'multiple_choice', 'A stage carpenter is modelling an arch for a roof brace for a coastal boardwalk. The graph of y = 1(x - 2)^2 + -3 is shown on the coordinate plane.', 'What are the coordinates of the vertex of the parabola?', '[{"id": "A", "text": "(2, 3)"}, {"id": "B", "text": "(2, -3)"}, {"id": "C", "text": "(-3, 2)"}, {"id": "D", "text": "(-2, -3)"}]'::jsonb, '{"type": "coordinate_plane", "x_min": -6, "x_max": 6, "y_min": -6, "y_max": 6, "x_label": "x", "y_label": "y", "points": [{"x": 2, "y": -3, "label": "vertex"}], "parabolas": [{"a": 1, "b": -4, "c": 1, "label": "y"}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-COORD-Q000', 'B', ARRAY['B']::TEXT[], 'In vertex form y = a(x - h)^2 + k the vertex is (h, k), so here it is (2, -3).', '{"D": "This negates the horizontal coordinate; in this form the vertex uses +h, not -h.", "A": "This negates the vertical coordinate, which shifts the parabola below the x-axis.", "C": "This swaps the two coordinates, which would be a different point entirely."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
