INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-COORD-Z000', 'C', ARRAY['C']::TEXT[], 'Factor the expression as (x - (1))(x - (3)) = 0, so the zeros are 1 and 3.', '{"D": "Both signs are flipped; the factors are x minus each zero.", "B": "Only one sign is flipped, which would come from a different pair of factors.", "A": "This shifts both zeros by two, a translation the graph does not show."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
