INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-DATA-E000', 'B', ARRAY['B']::TEXT[], 'Dividing consecutive values always gives 2, so g multiplies by 2 for each one-unit increase in x.', '{"C": "This is the starting value g(0), not the repeated factor.", "A": "This adds one to the multiplier; the ratio of consecutive values is 2.", "D": "This is the first value after zero, not the ratio between steps."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
