INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M13-DATA-B000', 'HDSAT-M13-DATA-B000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Percentages', 'Medium', 'multiple_choice', 'A landscape designer is comparing weekly counts at a triangular garden bed for a community garden. The bar graph shows library visits recorded over the periods shown.', 'How many more visits were recorded in Week 4 than in Week 3?', '[{"id": "A", "text": "90"}, {"id": "B", "text": "100"}, {"id": "C", "text": "180"}, {"id": "D", "text": "270"}]'::jsonb, '{"type": "bar_chart", "caption": "Library visits", "x_label": "Period", "y_label": "Number of visits", "series": [{"label": "Week 1", "value": 120}, {"label": "Week 2", "value": 150}, {"label": "Week 3", "value": 90}, {"label": "Week 4", "value": 180}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M13-DATA-B000', 'A', ARRAY['A']::TEXT[], 'Week 4 recorded 180 and Week 3 recorded 90, so the difference is 90 visits.', '{"D": "Adding the two bars gives a total, not the gap between them.", "B": "This is ten more than the gap; subtracting the two bar heights gives 90.", "C": "This is the taller bar by itself, without comparing it to the shorter one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
